// Satır: [İngilizce ad (listedeki ile birebir aynı), Latince ad, Türkçe ad, görev (bir-iki cümle), hafıza ipucu ya da '']
const K = [
// Deri ve meme
["skin of body", "Cutis", "Deri", "Vücudu dıştan saran en büyük organdır; korur, ısıyı düzenler, duyu alır ve D vitamini yapımında rol oynar. Epidermis ve dermis katlarından oluşur; altında deri altı dokusu (hipodermis) bulunur.", ""],
['interlobar adipose tissue of mammary gland','Corpus adiposum mammae','Memenin loblar arası yağ dokusu','Meme loblarının arasını dolduran yağ dokusudur; memenin biçimini ve büyüklüğünü büyük ölçüde bu doku belirler.',''],
['areolar tubercle','Tubercula areolae','Areola tüberkülleri (Montgomery tüberkülleri)','Areola üzerindeki küçük kabarcıklardır; altlarındaki areola bezleri emzirme sırasında meme başını yağlayıp korur. Gebelikte belirginleşir.',''],
['nipple','Papilla mammaria','Meme başı','Süt kanallarının (ductus lactiferi) dışarı açıldığı çıkıntıdır; düz kas lifleri sayesinde uyarıyla dikleşir. Genellikle 4. interkostal aralık düzeyindedir, dermatomu T4.','Meme başı = T4 dermatomu'],
['female areola','Areola mammae','Areola (meme başı halkası)','Meme başını çevreleyen koyu renkli deri alanıdır; yağ ve areola bezleri içerir. Gebelikte rengi koyulaşır.',''],
['mammary lobe','Lobi glandulae mammariae','Meme lobu','Meme bezinde 15-20 lob bulunur; her lob süt üreten lobüllerden oluşur ve kendi süt kanalıyla meme başına açılır.',''],
['main lactiferous duct','Ductus lactiferi','Süt kanalı','Her meme lobunun sütünü meme başına taşıyan ana kanaldır. Meme kanserlerinin çoğu kanal epitelinden köken alır (duktal karsinom).',''],
["lactiferous sinus", "Sinus lactiferi", "Süt sinüsü", "Klasik anatomi kitaplarına göre süt kanalının meme başına açılmadan hemen önceki genişlemiş bölümüdür. Emziren memede yapılan ultrason çalışmaları belirgin bir sinüs göstermemiştir; kanallar sütü depolamaktan çok taşır.", ""],
['suspensory ligament of breast','Ligamenta suspensoria mammaria','Memenin asıcı bağları (Cooper bağları)','Meme dokusunu deriye ve pektoral fasyaya bağlayan bağ dokusu şeritleridir. Tümör bu bağları çekerse deride çukurlaşma (çekinti) görülür.','Cooper bağı çekilirse deri çukurlaşır'],
// Göz
['retina','Retina','Retina (ağ tabaka)','Gözün en iç katıdır; çubuk ve koni hücreleri ışığı sinir sinyaline çevirir ve sinyal n. opticus ile beyne gider.',''],
['fovea centralis','Fovea centralis','Fovea centralis (merkezi çukur)','Macula lutea ortasındaki çukurdur; yalnız koni hücreleri içerir ve görmenin en keskin olduğu noktadır.','Fovea = en keskin görme, yalnız koni'],
['macula lutea','Macula lutea','Sarı nokta (makula)','Retinanın arka kutbunda, optik diskin lateralindeki sarımsı alandır; ayrıntılı ve renkli merkezi görmeyi sağlar. Yaşa bağlı makula dejenerasyonunda merkezi görme bozulur.',''],
['optic disc','Discus nervi optici','Optik disk (kör nokta)','Gangliyon hücresi aksonlarının gözü terk ederek n. opticus\'u oluşturduğu yerdir; fotoreseptör içermediği için kör noktadır. Kafa içi basınç artışında ödemi (papil ödemi) görülür.','Optik disk = kör nokta'],
['palpebral conjunctiva of upper eyelid','Tunica conjunctiva palpebrarum (palpebra superior)','Üst göz kapağı konjonktivası','Üst göz kapağının iç yüzünü döşeyen ince mukozadır; gözyaşı tabakasına katkı verir ve göz yüzeyini korur.',''],
['palpebral conjunctiva of lower eyelid','Tunica conjunctiva palpebrarum (palpebra inferior)','Alt göz kapağı konjonktivası','Alt göz kapağının iç yüzünü döşeyen mukozadır. Anemide rengi solar; muayenede alt kapak aşağı çekilerek bakılır.',''],
['pupil','Pupilla','Göz bebeği (pupilla)','İrisin ortasındaki açıklıktır; göze giren ışık miktarını ayarlar. M. sphincter pupillae (parasempatik, n. oculomotorius) daraltır, m. dilatator pupillae (sempatik) genişletir.','Parasempatik daraltır (miyozis), sempatik genişletir (midriyazis)'],
['ciliary processes','Processus ciliares','Siliyer çıkıntılar','Corpus ciliare üzerindeki kıvrımlardır; epiteli aköz hümörü (humor aquosus) salgılar ve zonula lifleri buraya tutunur.',''],
['ora serrata','Ora serrata','Ora serrata','Retinanın ışığa duyarlı bölümünün öne doğru bittiği testere dişi biçimli sınırdır; bunun önünde retina görmeyen ince bir epitel olarak devam eder.',''],
['corneoscleral junction','Limbus corneae','Limbus (kornea-sklera birleşimi)','Saydam korneanın beyaz skleraya geçtiği halkadır; kornea epitelinin kök hücreleri buradadır ve Schlemm kanalı bu bölgede yer alır.',''],
['scleral venous sinus','Sinus venosus sclerae','Schlemm kanalı','Limbus çevresindeki halka biçimli kanaldır; aköz hümörü toplayıp venlere boşaltır. Boşaltım bozulursa göz içi basıncı artar (glokom).','Schlemm tıkanırsa glokom'],
['aqueous humor of eyeball','Humor aquosus','Aköz hümör (ön kamara sıvısı)','Siliyer çıkıntılarda yapılan berrak sıvıdır; arka kamaradan pupilla yoluyla ön kamaraya geçer, kornea ve lensi besler, göz içi basıncını oluşturur.','Yol: siliyer çıkıntı → arka kamara → pupilla → ön kamara → trabeküler ağ → Schlemm'],
['ciliary body','Corpus ciliare','Siliyer cisim','İris ile koroid arasındaki halkadır; kası lensin biçimini değiştirerek uyumu (akomodasyon) sağlar, çıkıntıları aköz hümörü üretir.',''],
['ciliary muscle','Musculus ciliaris','Siliyer kas','Kasıldığında zonula lifleri gevşer, lens kalınlaşır ve yakına odaklanılır (akomodasyon). Parasempatik liflerle (n. oculomotorius, ganglion ciliare üzerinden) uyarılır.','Kas kasılır → zonula gevşer → lens şişer → yakın görme'],
['eye trabecular meshwork','Reticulum trabeculare','Trabeküler ağ','Ön kamara açısındaki süzgeç benzeri dokudur; aköz hümör buradan süzülerek Schlemm kanalına geçer.',''],
['bulbar conjunctiva','Tunica conjunctiva bulbi','Göz küresi konjonktivası','Skleranın ön bölümünü örten saydam mukozadır. Sarılık en erken burada (skleranın üstünde) fark edilir; konjonktivitte damarları belirginleşir.',''],
['humor of vitreous body','Humor vitreus','Vitreus sıvısı (camsı cisim)','Lens ile retina arasını dolduran saydam jeldir; göz küresinin biçimini korur ve retinayı yerinde tutmaya yardım eder.',''],
['dura mater','Dura mater','Dura mater (sert zar)','Beyin ve omuriliği saran üç zarın en dışta ve en kalın olanıdır; n. opticus çevresinde kılıf olarak devam eder ve skleraya karışır. Epidural kanama dura ile kemik arasında, subdural kanama dura ile araknoid arasında olur.','Dıştan içe: Dura, Araknoid, Pia (DAP)'],
['optic chiasma','Chiasma opticum','Optik kiazma','İki optik sinirin birleştiği yerdir; retinaların nazal yarısından gelen lifler burada karşıya geçer. Hipofiz tümörü ortadan basarsa iki gözün dış (temporal) görme alanı kaybolur: bitemporal hemianopsi.','Kiazma basısı = bitemporal hemianopsi'],
// Koku ve bazal önbeyin
['olfactory bulb','Bulbus olfactorius','Koku soğanı (bulbus olfactorius)','Lamina cribrosa üzerinde yer alır; burun mukozasından gelen koku sinir lifleri burada mitral hücrelerle sinaps yapar.',''],
['anterior olfactory nucleus','Nucleus olfactorius anterior','Ön koku çekirdeği','Bulbus ve tractus olfactorius içindeki nöron grubudur; koku bilgisini işler ve iki yarımküre arasında aktarır.',''],
['piriform cortex','Cortex piriformis','Piriform korteks','Birincil koku korteksinin ana bölümüdür; koku bilgisi talamusa uğramadan doğrudan buraya ulaşır.','Koku: talamusa uğramayan tek duyu'],
['frontal agranular insular cortex area fl','Cortex insularis agranularis frontalis','Frontal agranüler insula korteksi','İnsulanın ön-alt bölümünde, frontal loba komşu korteks alanıdır; iç organ duyuları, duygu ve koku-tat bilgisinin birleştirilmesinde rol alır. Modeldeki adı: frontal agranular insular cortex (area FI).',''],
['temporal agranular insular cortex area tl','Cortex insularis agranularis temporalis','Temporal agranüler insula korteksi','İnsulanın temporal loba komşu ön-alt bölümüdür; koku korteksiyle yakın bağlantılıdır ve iç organ duyularının işlenmesine katılır. Modeldeki adı: temporal agranular insular cortex (area TI).',''],
['head of caudate','Caput nuclei caudati','Kaudat çekirdeğin başı','Yan ventrikülün ön boynuzunun dış duvarını yapar. Bazal çekirdeklerin parçasıdır; hareketin ve bilişsel davranışın düzenlenmesinde görev alır. Huntington hastalığında küçülür.','Huntington: caput nuclei caudati atrofisi'],
['body of caudate','Corpus nuclei caudati','Kaudat çekirdeğin gövdesi','Yan ventrikülün gövdesinin tabanında, talamusun üst-dış kenarı boyunca uzanır; putamenle birlikte striatumu oluşturur.',''],
['tail of caudate','Cauda nuclei caudati','Kaudat çekirdeğin kuyruğu','Yan ventrikülün alt boynuzunun tavanında öne doğru uzanır ve amigdala yakınında sonlanır.',''],
['nucleus accumbens','Nucleus accumbens','Nucleus accumbens','Kaudat başı ile putamenin önde-altta birleştiği yerdedir; ödül, haz ve motivasyon devresinin merkezidir, bağımlılıkta önemli rol oynar.','Accumbens = ödül ve bağımlılık'],
['external segment of globus pallidus','Globus pallidus lateralis','Globus pallidus dış bölümü','Bazal çekirdeklerin dolaylı yolunda yer alır; subtalamik çekirdeğe baskılayıcı (GABA) lifler gönderir.',''],
['internal segment of globus pallidus','Globus pallidus medialis','Globus pallidus iç bölümü','Bazal çekirdeklerin ana çıkış çekirdeğidir; talamusu (VA/VL) baskılayarak hareketi frenler.',''],
['claustrum','Claustrum','Claustrum','Putamen ile insula korteksi arasındaki ince gri madde tabakasıdır; korteksin çok geniş alanlarıyla karşılıklı bağlantılıdır, işlevi tam bilinmemektedir.',''],
["basal forebrain", "Pars basalis telencephali", "Bazal önbeyin", "Önbeynin tabanındaki çekirdek grubudur (nucleus basalis Meynert dahil); kortekse asetilkolin gönderir. Alzheimer hastalığında bu kolinerjik nöronlar azalır.", "Meynert = asetilkolin; Alzheimer'da azalır"],
['septal nuclei','Nuclei septales','Septal çekirdekler','Septum pellucidum\'un altında yer alan limbik çekirdeklerdir; hipokampus ve hipotalamusla bağlantılıdır, ödül ve duygu davranışına katılır.',''],
['amygdaloid complex','Corpus amygdaloideum','Amigdala (badem cisim)','Temporal lobun ön-iç bölümünde, uncus derinindeki çekirdek topluluğudur; korku başta olmak üzere duygusal tepkiler ve duygusal bellekten sorumludur.','Amigdala = korku'],
['anterior amygdaloid area','Area amygdaloidea anterior','Ön amigdala alanı','Amigdalanın ön bölümündeki sınırları belirsiz geçiş alanıdır; koku yapıları ve bazal önbeyinle bağlantılıdır.',''],
['central nuclear group','Nucleus centralis amygdalae','Amigdalanın merkezi çekirdeği','Amigdalanın ana çıkış çekirdeğidir; hipotalamus ve beyin sapına giden liflerle korkunun bedensel belirtilerini (çarpıntı, donakalma) başlatır.',''],
['lateral nucleus','Nucleus lateralis amygdalae','Amigdalanın lateral çekirdeği','Amigdalanın ana giriş kapısıdır; korteks ve talamustan gelen duyu bilgisini alır, korku öğrenmesinde kilit rol oynar.',''],
['basolateral nucleus basal nucleus','Nucleus basalis lateralis amygdalae','Amigdalanın bazolateral (bazal) çekirdeği','Lateral çekirdekten aldığı bilgiyi işler; prefrontal korteks, hipokampus ve striatumla yoğun bağlantılıdır, duygusal belleğe katkı verir.',''],
['basomedial nucleus accessory basal nucleus','Nucleus basalis medialis amygdalae','Amigdalanın bazomedial (aksesuar bazal) çekirdeği','Amigdalanın bazal grubunun iç bölümüdür; hipotalamus ve hipokampusla bağlantı kurar.',''],
['anterior cortical nucleus','Nucleus corticalis anterior amygdalae','Amigdalanın ön kortikal çekirdeği','Amigdalanın yüzeyel (kortikal) grubundandır; koku soğanından doğrudan koku bilgisi alır.',''],
['posterior cortical nucleus','Nucleus corticalis posterior amygdalae','Amigdalanın arka kortikal çekirdeği','Amigdalanın yüzeyel grubunun arka bölümüdür; koku ile ilgili bilgileri işler.',''],
['medial nucleus','Nucleus medialis amygdalae','Amigdalanın medial çekirdeği','Koku bilgisi alır ve hipotalamusa lif gönderir; üreme ve sosyal davranışlarla ilişkilidir.',''],
['amygdalohippocampal area','Area amygdalohippocampalis','Amigdalohipokampal alan','Amigdala ile hipokampus başı arasındaki geçiş bölgesidir; iki yapı arasında bağlantı kurar.',''],
['bed nucleus of stria terminalis','Nucleus striae terminalis','Stria terminalis yatak çekirdeği','Stria terminalis\'in ön ucunda yer alır; amigdalanın uzantısı sayılır, uzun süreli kaygı ve stres yanıtında rol oynar.',''],
// Talamus ve çevresi
['thalamus','Thalamus','Talamus','Üçüncü ventrikülün iki yanındaki yumurta biçimli gri maddedir; koku dışındaki bütün duyuların kortekse giderken uğradığı ara istasyondur, hareket ve bilinç devrelerine de katılır.','Talamus = korteksin sekreteri'],
['anterior nuclear complex of thalamus','Nuclei anteriores thalami','Talamusun ön çekirdek grubu','Tractus mammillothalamicus ile corpus mammillare\'den bilgi alır ve gyrus cinguli\'ye iletir; Papez devresinin parçasıdır, bellekte rol oynar.',''],
["lateral dorsal nucleus of thalamus", "Nucleus dorsalis lateralis thalami", "Talamusun lateral dorsal çekirdeği", "Ön çekirdek grubunun arkaya uzantısı gibi çalışır; limbik sistem ve gyrus cinguli ile bağlantılıdır.", ""],
['mediodorsal nucleus of thalamus','Nucleus mediodorsalis thalami','Talamusun mediodorsal çekirdeği','Prefrontal korteksle karşılıklı bağlantılıdır; bellek, planlama ve duygu durumunda rol oynar. Wernicke-Korsakoff sendromunda etkilenir.',''],
['reuniens nucleus medioventral nucleus of thalamus','Nucleus reuniens thalami','Talamusun reuniens (medioventral) çekirdeği','Orta hat çekirdeklerindendir; prefrontal korteks ile hipokampus arasında köprü kurar.',''],
['lateral posterior nucleus of thalamus','Nucleus lateralis posterior thalami','Talamusun lateral posterior çekirdeği','Parietal asosiasyon korteksiyle bağlantılıdır; pulvinar ile birlikte duyuların birleştirilmesine ve görsel dikkate katkı verir.',''],
['pulvinar of thalamus','Pulvinar thalami','Pulvinar','Talamusun arka ucundaki en büyük çekirdek kitlesidir; görsel dikkat ve görsel bilginin asosiasyon korteksleriyle birleştirilmesinde rol alır.',''],
['ventral anterior nucleus of thalamus','Nucleus ventralis anterior thalami','Talamusun ventral anterior çekirdeği (VA)','Bazal çekirdeklerden (globus pallidus, substantia nigra) gelen bilgiyi premotor kortekse iletir; hareketin planlanmasına katılır.',''],
['ventral lateral nucleus of thalamus','Nucleus ventralis lateralis thalami','Talamusun ventral lateral çekirdeği (VL)','Serebellum ve bazal çekirdeklerden gelen bilgiyi motor kortekse iletir; hareketin eşgüdümünde rol alır.','VA/VL = motor talamus'],
['ventral posterior lateral nucleus','Nucleus ventralis posterolateralis thalami','Talamusun ventral posterolateral çekirdeği (VPL)','Gövde ve ekstremitelerden gelen dokunma, ağrı, ısı ve derin duyuyu (lemniscus medialis ve tractus spinothalamicus) alır, somatosensoriyel kortekse iletir.','VPL = vücut (Limbs), VPM = yüz (Mouth)'],
['ventral posterior medial nucleus','Nucleus ventralis posteromedialis thalami','Talamusun ventral posteromedial çekirdeği (VPM)','Yüzün duyusunu (n. trigeminus yolları) ve tat duyusunu alır, kortekse iletir.','VPM = yüz ve tat (Mouth)'],
['dorsal lateral geniculate nucleus','Nucleus dorsalis corporis geniculati lateralis','Corpus geniculatum laterale (dış dizsi cisim)','Görme yolunun talamustaki istasyonudur; tractus opticus lifleri burada sinaps yapar ve radiatio optica ile birincil görme korteksine gider.','Lateral = Light (görme), Medial = Music (işitme)'],
['medial geniculate nuclei','Nuclei corporis geniculati medialis','Corpus geniculatum mediale (iç dizsi cisim)','İşitme yolunun talamustaki istasyonudur; colliculus inferior\'dan gelen lifleri alır ve birincil işitme korteksine (Heschl girusu) gönderir.','Medial = Music (işitme)'],
['centromedian nucleus of thalamus','Nucleus centromedianus thalami','Talamusun sentromedian çekirdeği','İntralaminar çekirdeklerin en büyüğüdür; bazal çekirdeklerle bağlantılıdır, uyanıklık ve dikkatte rol oynar.',''],
['parafascicular nucleus of thalamus','Nucleus parafascicularis thalami','Talamusun parafasiküler çekirdeği','İntralaminar çekirdeklerdendir; striatuma lif gönderir, uyanıklık ve ağrının duygusal yönüyle ilişkilidir.',''],
['habenular nuclei','Nuclei habenulares','Habenula çekirdekleri','Epitalamusta, epifizin önünde yer alır; limbik sistemi orta beyne bağlar, ödül beklentisi ve olumsuz deneyimlere yanıtta rol oynar.',''],
['zona incerta','Zona incerta','Zona incerta','Talamus ile subtalamik çekirdek arasındaki ince gri madde tabakasıdır; çok sayıda bölgeyle bağlantılıdır, işlevi tam bilinmemektedir.',''],
["supraoptic region of hth", "Area hypothalamica anterior (regio supraoptica)", "Hipotalamusun supraoptik bölgesi", "Optik kiazmanın üstündeki hipotalamus bölümüdür; nucleus supraopticus ve paraventricularis burada ADH ve oksitosin üretir, nucleus suprachiasmaticus günlük ritmi ayarlar. Modeldeki adı: supraoptic region of HTH.", "ADH ve oksitosin burada yapılır, arka hipofizden salınır"],
['preoptic region of hth','Area preoptica','Hipotalamusun preoptik bölgesi','Hipotalamusun en ön bölümüdür; vücut ısısının düzenlenmesi, uyku ve GnRH salgısı ile üreme davranışında rol alır. Modeldeki adı: preoptic region of HTH.',''],
["tuberal region of hth", "Area hypothalamica intermedia (regio tuberalis)", "Hipotalamusun tuberal bölgesi", "Hipotalamusun orta bölümüdür; nucleus arcuatus, ventromedialis ve dorsomedialis buradadır. Ön hipofizi yöneten hormonlar buradan salınır; açlık ve tokluk burada düzenlenir. Modeldeki adı: tuberal region of HTH.", "Ventromedial = tokluk, lateral = açlık"],
['white matter of forebrain','Substantia alba cerebri','Önbeyin ak maddesi','Beyin yarımkürelerinin derinindeki miyelinli sinir lifleridir; korteks alanlarını birbirine ve alt merkezlere bağlar (asosiasyon, komissural ve projeksiyon lifleri).',''],
['fornix of brain','Fornix','Forniks','Hipokampusun ana çıkış yoludur; kavis çizerek corpus mammillare ve septal bölgeye ulaşır. Papez devresinin parçasıdır, hasarında bellek bozulur.',''],
['mammillothalamic tract','Fasciculus mammillothalamicus','Mamillotalamik yol','Corpus mammillare\'yi talamusun ön çekirdeklerine bağlar; Papez (bellek) devresinin halkalarından biridir.',''],
// Ventriküller
['anterior horn of lateral ventricle','Cornu frontale ventriculi lateralis','Yan ventrikülün ön (frontal) boynuzu','Yan ventrikülün frontal lob içindeki bölümüdür; dış duvarını kaudat çekirdeğin başı yapar. Foramen interventriculare (Monro) ile üçüncü ventriküle açılır.',''],
["body of lateral ventricle", "Pars centralis ventriculi lateralis", "Yan ventrikülün gövdesi", "Yan ventrikülün frontal ve parietal loblar içindeki orta bölümüdür; tabanında plexus choroideus beyin omurilik sıvısı üretir.", ""],
['posterior horn of lateral ventricle','Cornu occipitale ventriculi lateralis','Yan ventrikülün arka (oksipital) boynuzu','Yan ventrikülün oksipital loba uzanan bölümüdür; plexus choroideus içermez.',''],
['inferior horn of lateral ventricle','Cornu temporale ventriculi lateralis','Yan ventrikülün alt (temporal) boynuzu','Yan ventrikülün temporal lob içindeki bölümüdür; tabanında hipokampus, ön ucunda amigdala bulunur.',''],
['third ventricle','Ventriculus tertius','Üçüncü ventrikül','İki talamus arasındaki dar, orta hat boşluğudur; yan ventriküllerden Monro delikleriyle sıvı alır ve aqueductus cerebri ile dördüncü ventriküle iletir.',''],
['cerebellar vermis','Vermis cerebelli','Serebellum vermisi','Serebellumun orta hattaki bölümüdür; gövde dengesini ve yürümeyi düzenler. Hasarında gövde ataksisi ve geniş tabanlı yürüme görülür.','Vermis = gövde dengesi'],
['cerebellar deep nuclei','Nuclei cerebelli','Serebellumun derin çekirdekleri','Dıştan içe nucleus dentatus, emboliformis, globosus ve fastigii; serebellum korteksinin çıkışı bu çekirdekler üzerinden olur.','Dıştan içe: Dentatus, Emboliformis, Globosus, Fastigii (DEGF)'],
["white matter of hindbrain", "Substantia alba rhombencephali", "Arka beyin ak maddesi", "Arka beynin (pons, bulbus ve serebellum) miyelinli sinir lifleridir. Serebellumdaki bölümü (corpus medullare cerebelli) kesitte dallanan ağaç görünümü verir (arbor vitae).", ""],
['olfactory tract','Tractus olfactorius','Koku yolu (tractus olfactorius)','Bulbus olfactorius\'tan çıkan lifleri frontal lobun alt yüzünde, sulcus olfactorius içinde arkaya taşır ve koku korteksine ulaştırır.',''],
// Beyin korteksi
['triangular part of inferior frontal gyrus','Pars triangularis gyri frontalis inferioris','Alt frontal girusun üçgen bölümü','Baskın (çoğunlukla sol) yarımkürede pars opercularis ile birlikte Broca alanını oluşturur (Brodmann 45); konuşmanın üretilmesinde görev alır.','Broca = 44 + 45; hasarında anlar ama konuşamaz'],
['opercular part of inferior frontal gyrus','Pars opercularis gyri frontalis inferioris','Alt frontal girusun operküler bölümü','Baskın yarımkürede Broca alanının arka parçasıdır (Brodmann 44). Hasarında motor (Broca) afazisi olur: hasta anlar ama akıcı konuşamaz.',''],
['gyrus rectus','Gyrus rectus','Gyrus rectus (düz girus)','Frontal lobun alt yüzünde, orta hattın hemen yanında uzanır; dış yanında sulcus olfactorius ve koku yolu bulunur.',''],
['medial orbital gyrus','Gyrus orbitalis medialis','Medial orbital girus','Frontal lobun göz çukuru üstündeki alt yüzünde yer alır; orbitofrontal korteksin parçasıdır, karar verme ve ödül değerlendirmesine katılır.',''],
['intermediate orbital gyrus','Gyri orbitales (pars intermedia)','Ara orbital girus','Orbitofrontal korteksin orta bölümüdür; davranışın sosyal kurallara göre ayarlanmasında rol oynar. Modeldeki adı: intermediate orbital gyrus.',''],
['lateral orbital gyrus','Gyrus orbitalis lateralis','Lateral orbital girus','Orbitofrontal korteksin dış bölümüdür; dürtü kontrolü ve karar vermede görev alır. Orbitofrontal hasarda kişilik değişikliği ve dürtüsellik görülür.',''],
['anterior segment of paracentral lobule','Gyrus paracentralis anterior','Parasantral lobülün ön bölümü','Yarımkürenin iç yüzünde, birincil motor korteksin bacak ve ayak alanıdır. A. cerebri anterior besler; tıkanmasında karşı bacakta güçsüzlük olur.','ACA tıkanması = karşı bacak'],
['frontal operculum','Operculum frontale','Frontal operkulum','İnsulayı örten kapakçığın frontal lobdan gelen bölümüdür; alt frontal girusun parçalarını içerir.',''],
['supraparietal lobule','Lobulus parietalis superior','Üst parietal lobül','Parietal lobun sulcus intraparietalis üstündeki bölümüdür; duyuların birleştirilmesi, uzayda yön bulma ve el-göz eşgüdümünde rol alır. Modeldeki adı: supraparietal lobule.',''],
['supramarginal gyrus','Gyrus supramarginalis','Supramarginal girus','Sulcus lateralis\'in arka ucunu saran girustur (Brodmann 40); dilin ses yönünün işlenmesi ve beceri gerektiren hareketlerde rol alır.',''],
['angular gyrus','Gyrus angularis','Angular girus','Sulcus temporalis superior\'un arka ucunu saran girustur (Brodmann 39); okuma, yazma ve hesap yapmada görev alır. Baskın yarımküre hasarında Gerstmann sendromu görülür.','Gerstmann: yazamama, hesap yapamama, parmak tanıyamama, sağ-sol karıştırma'],
['precuneus cortex','Precuneus','Precuneus','Parietal lobun iç yüzünde, parasantral lobül ile cuneus arasındadır; görsel-uzaysal imgeleme, bellek ve benlik algısında rol oynar.',''],
['paracentral lobule caudal part','Gyrus paracentralis posterior','Parasantral lobülün arka bölümü','Yarımkürenin iç yüzünde, birincil duyu korteksinin bacak, ayak ve genital bölge alanıdır; idrar ve dışkı kontrolüne de katılır.',''],
['occipitotemporal fusiform gyrus temporal part','Gyrus occipitotemporalis lateralis (pars temporalis)','Fusiform girusun temporal bölümü','Temporal lobun alt yüzündedir; yüz ve nesne tanımada görev alır. Hasarında tanıdık yüzleri tanıyamama (prosopagnozi) görülür.','Fusiform = yüz tanıma'],
['transverse temporal gyrus heschls gyrus','Gyri temporales transversi','Heschl girusu (enine temporal girus)','Sulcus lateralis\'in derininde, üst temporal girusun üst yüzündedir; birincil işitme korteksidir (Brodmann 41; çevresindeki 42. alan çoğunlukla ikincil işitme alanı sayılır).','Heschl = işitme korteksi'],
['planum temporale','Planum temporale','Planum temporale','Heschl girusunun arkasındaki üçgen alandır; baskın yarımkürede Wernicke alanının parçasıdır ve çoğu insanda solda daha büyüktür.',''],
['temporal pole','Polus temporalis','Temporal kutup','Temporal lobun en ön ucudur; anlam belleği ve sosyal-duygusal işlemlerde rol alır.',''],
['planum polare','Planum polare','Planum polare','Üst temporal girusun üst yüzünde, Heschl girusunun önündeki alandır; işitsel asosiasyon korteksidir.',''],
['occipital pole','Polus occipitalis','Oksipital kutup','Oksipital lobun en arka ucudur; merkezi (makula) görmenin temsil edildiği birincil görme korteksi buradadır.',''],
['cuneus cortex','Cuneus','Cuneus','Oksipital lobun iç yüzünde, sulcus calcarinus\'un üstündeki kama biçimli alandır; alt görme alanından gelen bilgiyi alır.','Cuneus üstte, alt görme alanını görür'],
['lingual gyrus','Gyrus lingualis','Lingual girus','Oksipital lobun iç-alt yüzünde, sulcus calcarinus\'un altındadır; üst görme alanından gelen bilgiyi alır.','Lingualis altta, üst görme alanını görür'],
['occipital fusiform gyrus','Gyrus occipitotemporalis lateralis (pars occipitalis)','Fusiform girusun oksipital bölümü','Fusiform girusun oksipital lobdaki arka bölümüdür; renk ve biçim gibi üst düzey görsel işlemlere katılır.',''],
['inferior occipital gyrus','Gyrus occipitalis inferior','Alt oksipital girus','Oksipital lobun dış yüzünün alt bölümüdür; görsel asosiasyon korteksidir, yüz ve nesne tanımanın ilk basamaklarına katılır.',''],
['superior occipital gyrus','Gyrus occipitalis superior','Üst oksipital girus','Oksipital lobun dış yüzünün üst bölümüdür; görsel asosiasyon korteksidir, hareket ve uzaysal görmeyle ilişkilidir.',''],
['anterior cingulate gyrus','Gyrus cinguli (pars anterior)','Ön singulat girus','Corpus callosum\'un ön bölümünü saran limbik korteks; dikkat, hata izleme, motivasyon ve ağrının duygusal yönünde rol alır.',''],
['posterior cingulate gyrus','Gyrus cinguli (pars posterior)','Arka singulat girus','Corpus callosum\'un arka bölümünün üstündedir; bellek ve dinlenme halindeki beyin ağının (default mode) merkezlerindendir.',''],
['isthmus of cingulate gyrus','Isthmus gyri cinguli','Singulat girusun istmusu','Splenium\'un arkasında singulat girusun daralarak parahipokampal girusa geçtiği yerdir.',''],
['subcallosal area','Area subcallosa','Subkallozal alan','Corpus callosum\'un rostrumunun altındaki limbik korteks alanıdır; duygu durumunun düzenlenmesiyle ilişkilidir.',''],
['anterior parahippocampal gyrus','Gyrus parahippocampalis (pars anterior)','Parahipokampal girusun ön bölümü','Entorinal korteksi içerir; korteksten hipokampusa giden bilginin ana giriş kapısıdır. Alzheimer hastalığında en erken etkilenen bölgelerdendir.',''],
['posterior parahippocampal gyrus','Gyrus parahippocampalis (pars posterior)','Parahipokampal girusun arka bölümü','Mekân ve sahne tanıma ile uzaysal bellekte görev alır.',''],
['gyrus ambiens','Gyrus ambiens','Gyrus ambiens','Uncus üzerinde yer alan küçük bir kabarıklıktır; koku korteksinin ve entorinal bölgenin parçasıdır.',''],
['head of hippocampus','Caput hippocampi (pes hippocampi)','Hipokampusun başı','Hipokampusun yan ventrikülün alt boynuzundaki genişlemiş ön ucudur; amigdalanın hemen arkasındadır.',''],
['body of hippocampus','Corpus hippocampi','Hipokampusun gövdesi','Yan ventrikülün alt boynuzunun tabanında uzanır. Hipokampus yeni bilgilerin kalıcı belleğe aktarılmasını sağlar; iki taraflı hasarında yeni anı oluşturulamaz (anterograd amnezi).','Hipokampus = yeni anı kaydı'],
['tail of hippocampus','Cauda hippocampi','Hipokampusun kuyruğu','Hipokampusun splenium altına doğru incelen arka ucudur; lifleri fornikse katılır.',''],
['long insular gyri','Gyrus longus insulae','İnsulanın uzun girusu','İnsulanın sulcus centralis insulae arkasındaki bölümüdür; ağrı, ısı ve iç organ duyularının işlenmesinde rol alır.',''],
['short insular gyri','Gyri breves insulae','İnsulanın kısa girusları','İnsulanın ön bölümündeki giruslardır; tat, iç organ duyusu, duygu ve konuşmanın motor planlamasına katılır.',''],
['limen insula','Limen insulae','Limen insulae (insula eşiği)','İnsulanın ön-alt ucunda, frontal ve temporal lobların birleştiği eşiktir; a. cerebri media burada dallarına ayrılır.',''],
// Beyin sapı ve serebellum
['pretectal region','Area pretectalis','Pretektal alan','Orta beyin ile talamus arasındadır; ışık refleksinin merkezidir, retinadan gelen bilgiyi iki taraflı Edinger-Westphal çekirdeğine iletir. Bu yüzden bir göze ışık tutulunca iki pupilla da daralır.','Işık refleksi: n. II getirir, pretektum dağıtır, n. III daraltır'],
["substantia nigra", "Substantia nigra", "Substantia nigra (kara madde)", "Orta beyinde, crus cerebri ile tegmentum arasındadır; pars compacta'daki dopaminli nöronlar striatuma gider. Bu nöronların ölümü Parkinson hastalığına yol açar.", "Kara madde solarsa Parkinson"],
["cerebral peduncle", "Pedunculus cerebri", "Serebral pedinkül (pedunculus cerebri)", "Orta beynin ön bölümüdür; ön parçası (crus cerebri) korteksten omuriliğe ve beyin sapına inen motor lifleri (kortikospinal, kortikobulber, kortikopontin) taşır.", ""],
['superior cerebellar peduncle brachium conjunctivum','Pedunculus cerebellaris superior','Üst serebellar pedinkül (brachium conjunctivum)','Serebellumu orta beyne bağlar; serebellumun ana çıkış yoludur, lifleri çaprazlaşıp nucleus ruber ve talamusa gider.','Üst pedinkül = çıkış'],
['cerebral aqueduct','Aqueductus mesencephali','Aqueductus cerebri (Sylvius kanalı)','Üçüncü ventrikülü dördüncü ventriküle bağlayan dar kanaldır. Tıkanması tıkayıcı (non-kommunikan) hidrosefaliye yol açar.','BOS yolunun en dar yeri'],
['paravermis of cerebellum','Pars intermedia hemispherii cerebelli','Serebellumun paravermis bölgesi','Vermisin hemen yanındaki ara bölgedir; kol ve bacakların uç bölümlerindeki hareketleri düzeltir, çıkışı nucleus interpositus üzerinden olur.',''],
['lateral hemisphere of cerebellum','Hemispherium cerebelli (pars lateralis)','Serebellum yarımküresinin lateral bölümü','Hareketlerin planlanması ve zamanlanmasında rol alır; çıkışı nucleus dentatus üzerinden olur. Hasarında aynı taraf kol ve bacakta beceriksizlik, intansiyonel tremor ve dismetri görülür.','Serebellum hasarı aynı tarafı etkiler'],
['pontine nuclear group','Nuclei pontis','Pons çekirdekleri','Ponsun ön bölümüne dağılmış çekirdeklerdir; beyin korteksinden gelen bilgiyi orta serebellar pedinkül ile karşı serebellum yarımküresine aktarır.',''],
['pontine tegmentum','Tegmentum pontis','Pons tegmentumu','Ponsun dördüncü ventrikül tabanına bakan arka bölümüdür; V, VI, VII ve VIII. kafa çiftlerinin çekirdeklerini ve retiküler formasyonu içerir.',''],
['pyramidal part of medulla oblongata','Pyramis medullae oblongatae','Bulbus piramidi','Bulbusun ön yüzündeki kabarıklıktır; kortikospinal yolu taşır. Liflerin yaklaşık yüzde 85-90\'ı alt uçta karşıya geçer (decussatio pyramidum).','Piramitler çaprazlaşır: sol beyin sağ vücudu yönetir'],
['tegmentum of medulla oblongata','Tegmentum medullae oblongatae','Bulbus tegmentumu','Bulbusun arka bölümüdür; IX, X ve XII. kafa çiftlerinin çekirdeklerini (XI. kafa çiftinin çekirdeği çoğunlukla boyun omuriliğindedir), solunum ve dolaşım merkezlerini içerir.',''],
['inferior olive','Complexus olivaris inferior','Alt oliva çekirdeği','Bulbusta piramidin dış yanındaki kabarıklığı (oliva) oluşturur; tırmanıcı liflerini alt serebellar pedinkül ile karşı serebelluma gönderir, hareket öğrenmesinde rol alır.',''],
['middle cerebellar peduncle','Pedunculus cerebellaris medius','Orta serebellar pedinkül (brachium pontis)','Ponsu serebelluma bağlayan en büyük pedinküldür; pons çekirdeklerinden gelen (korteks kaynaklı) lifleri serebelluma taşır.','Orta pedinkül = yalnız giriş'],
['central canal of medulla oblongata','Canalis centralis','Bulbusun merkezi kanalı','Bulbusun alt (kapalı) bölümünde omurilikteki merkezi kanalın devamıdır; yukarıda dördüncü ventriküle açılır.',''],
['midline nuclear complex','Nuclei mediani thalami','Talamusun orta hat çekirdekleri','Üçüncü ventrikül duvarına komşu ince çekirdek grubudur; limbik sistem ve hipokampusla bağlantılıdır, uyanıklık ve belleğe katkı verir.',''],
['lateral olfactory gyrus','Gyrus olfactorius lateralis','Lateral olfaktor girus','Stria olfactoria lateralis\'i örten ince korteks şerididir; koku liflerini piriform kortekse taşır.',''],
['parietal operculum','Operculum parietale','Parietal operkulum','İnsulayı örten kapakçığın parietal lobdan gelen bölümüdür; ikincil somatosensoriyel korteksi içerir.',''],
['optic radiation','Radiatio optica','Optik radyasyon (görme ışınımı)','Corpus geniculatum laterale\'den birincil görme korteksine giden liflerdir. Temporal lobdan dolanan alt lifler (Meyer halkası) kesilirse karşı tarafta üst çeyrek görme kaybı olur.','Meyer halkası = üst çeyrek kaybı'],
['posteroventral putamen','Putamen (pars posteroventralis)','Putamenin arka-alt bölümü','Putamen, kaudat çekirdekle birlikte striatumu oluşturur ve hareketin düzenlenmesinde görev alır. Arka bölümü duyu-motor kortekslerle bağlantılıdır; Parkinson hastalığında dopamin kaybı en erken burada belirir.',''],
['atrium of lateral ventricle','Atrium ventriculi lateralis','Yan ventrikülün atriumu (trigon)','Yan ventrikülün gövde, arka boynuz ve alt boynuzunun birleştiği geniş bölümdür; plexus choroideus burada en kalındır (glomus choroideum).',''],
['paracingulate gyrus','Gyrus paracingularis','Parasingulat girus','Ön singulat girusun üstünde, ona paralel uzanan ve herkeste bulunmayan girustur; medial prefrontal korteksin parçasıdır.',''],
["rostral gyrus", "Gyrus rostralis", "Rostral girus", "Frontal lobun iç yüzünde, gyrus rectus'un hemen üstünde ve ona paralel uzanan girustur; medial prefrontal korteksin parçasıdır.", ""],
['frontomarginal gyrus','Gyrus frontomarginalis','Frontomarjinal girus','Frontal kutbun alt kenarında, orbital yüzeye geçişteki girustur; prefrontal korteksin parçasıdır.',''],
['frontal pole','Polus frontalis','Frontal kutup','Frontal lobun en ön ucudur (Brodmann 10); planlama ve birden çok işi birlikte yürütme gibi üst düzey bilişsel işlevlerde rol alır.',''],
['inferior cerebellar peduncle','Pedunculus cerebellaris inferior','Alt serebellar pedinkül (corpus restiforme)','Bulbusu serebelluma bağlar; omurilikten (tractus spinocerebellaris posterior), alt olivadan ve denge çekirdeklerinden gelen lifleri taşır.',''],
['perirhinal gyrus rostral part of fugt','Cortex perirhinalis','Peririnal korteks','Temporal lobun iç-alt yüzünde, sulcus collateralis çevresindeki kortekstir; nesne tanıma belleğinde rol alır ve hipokampusa bilgi gönderir. Modeldeki adı: perirhinal gyrus (rostral part of FuGt; fusiform girusun temporal bölümünün ön parçası).',''],
['piriform region','Regio piriformis','Piriform bölge','Uncus ve çevresindeki koku korteksi alanıdır; birincil koku korteksini içerir. Buradan başlayan nöbetlerde hasta olmayan kötü kokular duyabilir (unsinat nöbet).',''],
['red nucleus','Nucleus ruber','Nucleus ruber (kırmızı çekirdek)','Orta beyin tegmentumundadır; serebellumdan lif alır, alt olivaya ve omuriliğe (tractus rubrospinalis) lif gönderir. Kolun fleksör kaslarının tonusunda rol oynar.',''],
['subthalamic nucleus','Nucleus subthalamicus','Subtalamik çekirdek','Talamusun altında, bazal çekirdeklerin dolaylı yolunda yer alır; uyarıcı (glutamat) lifler gönderir. Hasarında karşı tarafta savurucu istemsiz hareketler (hemiballismus) olur.','Subtalamik hasar = hemiballismus'],
["mammillary region of hth", "Area hypothalamica posterior (regio mammillaris)", "Hipotalamusun mamiller bölgesi", "Hipotalamusun arka bölümüdür; corpus mammillare fornixten bilgi alıp talamusa iletir (bellek devresi). Tiamin (B1) eksikliğinde hasar görür: Wernicke-Korsakoff sendromu. Modeldeki adı: mammillary region of HTH.", "Alkol + B1 eksikliği = corpus mammillare hasarı"],
['midbrain tegmentum','Tegmentum mesencephali','Orta beyin tegmentumu','Orta beynin aqueductus önündeki bölümüdür; nucleus ruber, III ve IV. kafa çifti çekirdekleri ile retiküler formasyonu içerir.',''],
// Omurilik segmentleri
['c1 segment of cervical spinal cord','Segmentum cervicale I medullae spinalis','Omuriliğin C1 segmenti','Birinci boyun sinirini verir; bu sinir kafatası ile atlas arasından çıkar ve çoğunlukla deri duyusu taşımaz, ense altı kaslarını çalıştırır.','8 boyun siniri var ama 7 boyun omuru'],
['c2 segment of cervical spinal cord','Segmentum cervicale II medullae spinalis','Omuriliğin C2 segmenti','İkinci boyun sinirini verir; dermatomu kafa derisinin arka bölümüdür (n. occipitalis major).',''],
['c3 segment of cervical spinal cord','Segmentum cervicale III medullae spinalis','Omuriliğin C3 segmenti','Dermatomu boynun yan ve ön bölümüdür. C3-C5 segmentleri n. phrenicus ile diyaframı çalıştırır.','C3, 4, 5 diyaframı canlı tutar'],
['c4 segment of cervical spinal cord','Segmentum cervicale IV medullae spinalis','Omuriliğin C4 segmenti','Dermatomu omuz üstü ve köprücük kemiği bölgesidir; n. phrenicus\'a en çok katkıyı verir. Bu düzeyin üstündeki hasarlarda solunum durabilir.',''],
['c5 segment of cervical spinal cord','Segmentum cervicale V medullae spinalis','Omuriliğin C5 segmenti','Plexus brachialis\'in ilk köküdür; m. deltoideus ile omuz abduksiyonunu ve biceps refleksini sağlar, dermatomu kolun dış yüzüdür.','Biceps refleksi C5-C6'],
['c6 segment of cervical spinal cord','Segmentum cervicale VI medullae spinalis','Omuriliğin C6 segmenti','Dirsek fleksiyonu ve el bileği ekstansiyonuna katılır; dermatomu ön kolun dış yüzü ve başparmaktır.','C6 = başparmak'],
['c7 segment of cervical spinal cord','Segmentum cervicale VII medullae spinalis','Omuriliğin C7 segmenti','M. triceps brachii ile dirsek ekstansiyonunu ve triceps refleksini sağlar; dermatomu orta parmaktır.','C7 = orta parmak, triceps refleksi'],
['c8 segment of cervical spinal cord','Segmentum cervicale VIII medullae spinalis','Omuriliğin C8 segmenti','Parmak fleksiyonuna katılır; dermatomu küçük parmak ve elin iç kenarıdır. C8 siniri C7 ile T1 omurları arasından çıkar.','C8 = küçük parmak'],
['first thoracic spinal cord segment','Segmentum thoracicum I medullae spinalis','Omuriliğin T1 segmenti','Plexus brachialis\'in son köküdür; elin küçük kaslarını çalıştırır, dermatomu ön kolun iç yüzüdür. T1-L2 arası yan boynuzda sempatik nöronlar bulunur.','Sempatik çıkış T1-L2'],
['second thoracic spinal cord segment','Segmentum thoracicum II medullae spinalis','Omuriliğin T2 segmenti','Dermatomu koltuk altı ve kolun iç-üst bölümüdür; interkostal kasları çalıştırır.',''],
['third thoracic spinal cord segment','Segmentum thoracicum III medullae spinalis','Omuriliğin T3 segmenti','Üçüncü interkostal siniri verir; göğüs duvarında kuşak biçimli deri alanını ve interkostal kasları uyarır.',''],
['fourth thoracic spinal cord segment','Segmentum thoracicum IV medullae spinalis','Omuriliğin T4 segmenti','Dermatomu meme başı düzeyidir. T1-T4 segmentleri kalbe giden sempatik lifleri verir.','T4 = meme başı'],
['fifth thoracic spinal cord segment','Segmentum thoracicum V medullae spinalis','Omuriliğin T5 segmenti','Beşinci interkostal siniri verir. T5-T9 segmentlerinden çıkan sempatik lifler n. splanchnicus major\'u oluşturur.',''],
['seventh thoracic spinal cord segment','Segmentum thoracicum VII medullae spinalis','Omuriliğin T7 segmenti','Dermatomu göğüs kemiğinin alt ucu (processus xiphoideus) düzeyine yakındır; karın ön duvarının üst bölümünü de uyarır.',''],
['eighth thoracic spinal cord segment','Segmentum thoracicum VIII medullae spinalis','Omuriliğin T8 segmenti','Dermatomu kaburga yayının hemen altındaki karın üst bölümüdür; karın kaslarının üst bölümünü çalıştırır.',''],
['sixth thoracic spinal cord segment','Segmentum thoracicum VI medullae spinalis','Omuriliğin T6 segmenti','Dermatomu yaklaşık olarak processus xiphoideus düzeyidir; interkostal kasları çalıştırır.',''],
['ninth thoracic spinal cord segment','Segmentum thoracicum IX medullae spinalis','Omuriliğin T9 segmenti','Dermatomu göbeğin biraz üstündeki karın bölümüdür; karın kaslarını çalıştırır.',''],
['tenth thoracic spinal cord segment','Segmentum thoracicum X medullae spinalis','Omuriliğin T10 segmenti','Dermatomu göbek düzeyidir. Apandisitin başlangıçtaki göbek çevresi ağrısı bu segmente yansıyan ağrıdır.','T10 = göbek (umbilicus)'],
['eleventh thoracic spinal cord segment','Segmentum thoracicum XI medullae spinalis','Omuriliğin T11 segmenti','Dermatomu göbek ile kasık arasındaki karın alt bölümüdür; karın kaslarının alt bölümünü çalıştırır.',''],
['twelfth thoracic spinal cord segment','Segmentum thoracicum XII medullae spinalis','Omuriliğin T12 segmenti','N. subcostalis\'i verir; dermatomu kasık bağının hemen üstündeki karın alt bölümüdür.',''],
['first lumbar spinal cord segment','Segmentum lumbale I medullae spinalis','Omuriliğin L1 segmenti','Dermatomu kasık bölgesidir (n. iliohypogastricus, n. ilioinguinalis). Kremaster refleksi L1-L2 üzerinden çalışır.','L1 = kasık (inguinal ligament)'],
['second lumbar spinal cord segment','Segmentum lumbale II medullae spinalis','Omuriliğin L2 segmenti','Kalça fleksiyonuna (m. iliopsoas) katılır; dermatomu uyluğun ön-üst bölümüdür. Sempatik çıkışın son segmentidir.',''],
['third lumbar spinal cord segment','Segmentum lumbale III medullae spinalis','Omuriliğin L3 segmenti','Diz ekstansiyonuna (m. quadriceps femoris) katılır; dermatomu uyluğun ön-alt bölümü ve dizin iç yüzüdür.',''],
['fourth lumbar spinal cord segment','Segmentum lumbale IV medullae spinalis','Omuriliğin L4 segmenti','Patella refleksinin ana segmentidir; ayağı yukarı çekmeye (m. tibialis anterior) katılır, dermatomu bacağın iç yüzü ve iç ayak bileğidir.','Patella refleksi L3-L4'],
['fifth lumbar spinal cord segment','Segmentum lumbale V medullae spinalis','Omuriliğin L5 segmenti','Ayak başparmağını yukarı kaldırır (m. extensor hallucis longus); dermatomu bacağın dış yüzü, ayak sırtı ve başparmaktır. Bel fıtığında en sık etkilenen köklerdendir.','L5 = ayak başparmağını kaldırma'],
['first sacral spinal cord segment','Segmentum sacrale I medullae spinalis','Omuriliğin S1 segmenti','Ayağı aşağı basmayı (m. triceps surae) ve Aşil refleksini sağlar; dermatomu ayağın dış kenarı ve küçük parmaktır.','Aşil refleksi S1'],
['second sacral spinal cord segment','Segmentum sacrale II medullae spinalis','Omuriliğin S2 segmenti','Dermatomu uyluğun arka yüzüdür. S2-S4 segmentleri pelvis organlarına parasempatik lifleri (nn. splanchnici pelvici) ve n. pudendus\'u verir.','S2, 3, 4 idrarı ve dışkıyı tutar'],
['third sacral spinal cord segment','Segmentum sacrale III medullae spinalis','Omuriliğin S3 segmenti','Dermatomu kalçanın iç bölümü ve perinedir; mesane, rektum ve cinsel organların sinir kontrolüne katılır.',''],
['fourth sacral spinal cord segment','Segmentum sacrale IV medullae spinalis','Omuriliğin S4 segmenti','Dermatomu anüs çevresidir; dış anal sfinkter ve pelvis tabanı kaslarının kontrolüne katılır. Anüs çevresi duyusunun korunması omurilik hasarının tam olmadığını gösterir.',''],
['tendon of quadriceps femoris','Tendo musculi quadricipitis femoris','Kuadriseps tendonu','M. quadriceps femoris\'in dört başının birleşerek patellanın üst kenarına yapıştığı kiriştir; patella üzerinden lig. patellae olarak tibiaya devam eder ve dizi ekstansiyona getirir.',''],
// Gebelik
['basal plate','Lamina basalis placentae','Plasentanın bazal plağı','Plasentanın anneye bakan yüzüdür; decidua basalis ve ona tutunan trofoblastlardan oluşur, annenin spiral arterleri buradan villuslar arası boşluğa açılır.',''],
['chorionic plate','Lamina chorionica','Koryon plağı','Plasentanın fetüse bakan yüzüdür; göbek kordonu damarlarının dalları burada yayılır ve koryon villusları buradan çıkar. Üstünü amniyon örter.',''],
['placenta vessels','Vasa placentae','Plasenta damarları','Göbek kordonu damarlarının koryon plağında yayılan dallarıdır; villuslara girerek anne kanıyla gaz, besin ve atık alışverişini sağlar. Anne ve fetüs kanı normalde birbirine karışmaz.',''],
['amnion','Amnion','Amniyon zarı','Fetüsü ve amniyon sıvısını saran en içteki ince zardır; fetüsü darbelerden korur ve hareket etmesine izin verir.',''],
['umbilical cord','Funiculus umbilicalis','Göbek kordonu','Fetüsü plasentaya bağlar; içinde iki a. umbilicalis ve bir v. umbilicalis bulunur, bunları Wharton jölesi korur.','2 arter + 1 ven'],
['umbilical artery','Arteria umbilicalis','Göbek arteri','Fetüsün oksijeni azalmış kanını a. iliaca interna\'dan plasentaya taşır; iki tanedir. Doğumdan sonra kapanan bölümü lig. umbilicale mediale olur.','Arter ama oksijeni azalmış kan taşır'],
['umbilical vein','Vena umbilicalis','Göbek veni','Plasentadan oksijenlenmiş kanı fetüse taşır; tektir. Kanın büyük bölümü ductus venosus ile karaciğeri atlayıp v. cava inferior\'a geçer. Doğumdan sonra lig. teres hepatis olur.','Ven ama oksijenli kan taşır'],
// Kadın üreme sistemi
['vagina','Vagina','Vajina','Serviksten vulvaya uzanan kas-zar yapılı kanaldır; doğum kanalının alt bölümüdür. Arka forniksi excavatio rectouterina (Douglas boşluğu) ile komşudur.',''],
["cervicovaginal junction", "Junctio cervicovaginalis", "Serviks-vajina birleşimi", "Serviksin vajinaya uzanan bölümünün vajina duvarıyla birleştiği yerdir; çevresinde vajina forniksleri oluşur. Modeldeki adı: cervicovaginal junction.", ""],
['ampulla of uterine tube','Ampulla tubae uterinae','Tuba uterinanın ampullası','Tubanın en uzun ve en geniş bölümüdür. Döllenmenin en sık gerçekleştiği yerdir; dış gebelik de en sık burada görülür.','Ampulla = döllenme yeri'],
['isthmus of uterine tube','Isthmus tubae uterinae','Tuba uterinanın istmusu','Tubanın uterusa yakın, dar ve kalın duvarlı bölümüdür. Tüp bağlama (tubal ligasyon) genellikle bu bölümde yapılır.',''],
['fimbria of uterine tube','Fimbriae tubae uterinae','Tuba uterinanın fimbriaları (saçakları)','İnfundibulumun kenarındaki parmak biçimli saçaklardır; yumurtlama sırasında overin yüzeyini süpürerek oositi yakalar. En uzunu (fimbria ovarica) overe tutunur.',''],
['infundibulum of uterine tube','Infundibulum tubae uterinae','Tuba uterinanın infundibulumu','Tubanın overe yakın, huni biçimli dış ucudur; karın boşluğuna açılır ve kenarında fimbrialar bulunur.',''],
['uterovesical pouch','Excavatio vesicouterina','Mesane-uterus çukuru','Periton mesanenin üstünden uterusun ön yüzüne atlarken oluşan sığ çukurdur. Arkadaki Douglas boşluğundan (excavatio rectouterina) daha sığdır.',''],
['round ligament of uterus','Ligamentum teres uteri','Uterusun yuvarlak bağı','Uterus köşesinden başlar, kasık kanalından (canalis inguinalis) geçer ve labium majus\'ta sonlanır; uterusu öne eğik tutmaya yardım eder. Gubernaculum kalıntısıdır.','Kadında kasık kanalından geçen yapı'],
['uterosacral ligament','Ligamentum rectouterinum (uterosacrale)','Uterosakral bağ','Serviksi rektumun iki yanından sakruma bağlar; uterusu arkaya-yukarı çekerek sarkmasını önler.',''],
['cardinal ligament','Ligamentum cardinale (ligamentum transversum cervicis)','Kardinal bağ (Mackenrodt bağı)','Serviksi pelvis yan duvarına bağlar; uterusun en önemli destek bağıdır ve içinde a. uterina seyreder. Zayıflaması uterus sarkmasına (prolapsus) yol açar.','Kardinal bağda a. uterina'],
['suspensory ligament of ovary','Ligamentum suspensorium ovarii','Overin asıcı bağı (infundibulopelvik bağ)','Overi pelvis yan duvarına bağlayan periton kıvrımıdır; içinden a. ve v. ovarica geçer. Over ameliyatında bağlanırken hemen altındaki üretere dikkat edilir.','Suspensorium = over damarları'],
['ovarian ligament','Ligamentum ovarii proprium','Overin öz bağı','Overi uterus köşesine bağlar; içinde damar taşımaz. Gubernaculum\'un üst bölümünün kalıntısıdır.',''],
['broad ligament of uterus','Ligamentum latum uteri','Uterusun geniş bağı','Uterusun yan kenarlarından pelvis yan duvarına uzanan çift katlı periton yaprağıdır; mesosalpinx, mesovarium ve mesometrium bölümlerinden oluşur.',''],
['mesosalpinx','Mesosalpinx','Mezosalpinks','Geniş bağın tuba uterinayı saran üst bölümüdür; tubanın damarlarını taşır.',''],
['mesovarium','Mesovarium','Mezovaryum','Geniş bağın arka yüzünden overe uzanan kısa periton kıvrımıdır; overin damar ve sinirleri hilusa buradan girer.',''],
['ovary','Ovarium','Over (yumurtalık)','Oosit üreten ve östrojen ile progesteron salgılayan çift organdır. Lenfi bel bölgesindeki (paraaortik) lenf düğümlerine gider; sağ v. ovarica v. cava inferior\'a, sol v. ovarica sol v. renalis\'e dökülür.','Sol over veni → sol renal ven'],
['abdominal ostium of uterine tube','Ostium abdominale tubae uterinae','Tuba uterinanın karın ağzı','Tubanın periton boşluğuna açılan dış ağzıdır. Bu açıklık nedeniyle kadında periton boşluğu dış ortamla dolaylı olarak bağlantılıdır; enfeksiyon bu yolla peritona yayılabilir.',''],
['body of uterus','Corpus uteri','Uterus gövdesi','Uterusun fundus ile serviks arasındaki ana bölümüdür; embriyo çoğunlukla gövdenin üst bölümüne yerleşir. Duvarı endometrium, myometrium ve perimetrium katlarından oluşur.',''],
['fundus of uterus','Fundus uteri','Uterus fundusu','Uterusun tubaların giriş düzeyinin üstünde kalan kubbe bölümüdür. Gebelikte fundus yüksekliği ölçülerek gebelik haftası tahmin edilir (20. haftada göbek düzeyi).',''],
['cornua','Cornu uteri','Uterus köşesi (boynuzu)','Uterusun üst-yan köşesidir; tuba uterina buradan uterusa girer, lig. teres uteri ve lig. ovarii proprium da buraya tutunur.',''],
['lower uterine segment','Isthmus uteri','Uterusun alt segmenti (istmus)','Gövde ile serviks arasındaki dar bölümdür; gebeliğin sonlarında incelip genişler. Sezaryen kesisi genellikle buradan yapılır.',''],
['posterior wall of uterus','Facies intestinalis (posterior) uteri','Uterusun arka duvarı','Bağırsaklara bakan dışbükey yüzdür; peritonla örtülüdür ve arkasında excavatio rectouterina (Douglas boşluğu) bulunur.',''],
['anterior wall of uterus','Facies vesicalis (anterior) uteri','Uterusun ön duvarı','Mesaneye bakan yüzdür; uterus normalde mesanenin üstüne doğru öne eğik ve bükük durur (anteversiyon, antefleksiyon).',''],
['uterine cervix','Cervix uteri','Serviks (rahim boynu)','Uterusun vajinaya açılan dar alt bölümüdür. Rahim ağzı kanseri en sık yassı ve silindirik epitelin birleştiği dönüşüm bölgesinden çıkar; taramada buradan sürüntü (smear) alınır, başlıca nedeni HPV\'dir.',''],
['internal cervical os','Ostium anatomicum uteri internum','Serviksin iç ağzı','Serviks kanalının uterus boşluğuna açıldığı üst ağızdır; gebelikte kapalı kalarak fetüsü içeride tutar.',''],
['external cervical os','Ostium uteri','Serviksin dış ağzı','Serviks kanalının vajinaya açıldığı alt ağızdır; doğum yapmamış kadında yuvarlak, vajinal doğum yapmış kadında enine yarık biçimindedir.',''],
// Sindirim sistemi
['palatine tonsil','Tonsilla palatina','Damak bademciği','Arcus palatoglossus ile arcus palatopharyngeus arasındaki çukurda yer alan lenf dokusudur; ağızdan giren mikroplara karşı ilk savunmayı yapar. Ana arteri a. facialis\'in dalı olan ramus tonsillaris\'tir.',''],
['hepatic flexure of colon','Flexura coli dextra','Kolonun sağ (karaciğer) kıvrımı','Çıkan kolonun enine kolona döndüğü yerdir; karaciğerin sağ lobunun altında, sağ böbreğin önündedir.',''],
['vermiform appendix','Appendix vermiformis','Apendiks','Çekumun arka-iç yüzünden çıkan kör uçlu, lenf dokusundan zengin tüptür. İltihabında (apandisit) ağrı önce göbek çevresinde başlar, sonra McBurney noktasına yerleşir; a. appendicularis besler.','McBurney: göbek ile sağ kalça kemiği çıkıntısı arasının dış 1/3 noktası'],
["ileocecal valve", "Ostium ileale (valva ileocaecalis)", "İleoçekal kapak", "İleumun kalın bağırsağa açıldığı yerdeki kapaktır; kalın bağırsak içeriğinin ince bağırsağa geri kaçmasını önler.", ""],
['caecum','Caecum','Çekum (kör bağırsak)','Kalın bağırsağın sağ kalça çukurundaki kese biçimli ilk bölümüdür; ileum ve apendiks buraya açılır.',''],
['sigmoid colon','Colon sigmoideum','Sigmoid kolon','İnen kolonu rektuma bağlayan S biçimli, mezosu olan hareketli bölümdür. Kendi çevresinde dönmesi (volvulus) ve divertiküller en sık burada görülür.',''],
['splenic flexure of colon','Flexura coli sinistra','Kolonun sol (dalak) kıvrımı','Enine kolonun inen kolona döndüğü yerdir; sağ kıvrımdan daha yukarıdadır. A. mesenterica superior ve inferior alanlarının sınırı olduğundan kan akımı azaldığında en kolay etkilenen yerdir.',''],
['superior part of duodenum','Pars superior duodeni','Duodenumun üst bölümü','Pilordan sonra gelen ilk bölümdür; L1 düzeyindedir ve başlangıcı periton içidir. Arkasından a. gastroduodenalis geçer.',''],
['duodenal ampulla','Ampulla duodeni (bulbus duodeni)','Duodenum ampullası (bulbus)','Duodenumun pilordan hemen sonraki genişlemiş ilk 2 santimetresidir. Duodenum ülserleri en sık buradadır; arka duvar ülseri a. gastroduodenalis\'i delip kanatabilir.','Ülser en sık bulbusta'],
['descending part of duodenum','Pars descendens duodeni','Duodenumun inen bölümü','Pankreas başının sağında aşağı iner; safra ve pankreas kanalları arka-iç duvarındaki papilla duodeni major\'a açılır.',''],
["sphincter of hepatopancreatic ampulla", "Musculus sphincter ampullae", "Oddi sfinkteri", "Hepatopankreatik ampullayı saran düz kastır; safra ve pankreas salgısının duodenuma akışını ayarlar. Kolesistokinin etkisiyle gevşer.", "Oddi kapıyı tutar, kolesistokinin açar"],
['ascending part of duodenum','Pars ascendens duodeni','Duodenumun çıkan bölümü','Aortun solunda yukarı çıkar ve flexura duodenojejunalis ile jejunuma geçer; bu kıvrımı Treitz bağı asar. Treitz bağı üst ve alt sindirim sistemi kanamalarının ayrım sınırıdır.',''],
['horizontal part of duodenum','Pars horizontalis duodeni','Duodenumun yatay bölümü','L3 düzeyinde sağdan sola geçer; önünden a. ve v. mesenterica superior, arkasından aorta ve v. cava inferior geçer. İki arter arasında sıkışabilir (a. mesenterica superior sendromu).',''],
['jejunum','Jejunum','Jejunum (boş bağırsak)','İnce bağırsağın duodenumdan sonraki yaklaşık beşte ikilik bölümüdür; emilimin çoğu burada olur. İleuma göre duvarı kalın, kıvrımları (plicae circulares) sık, damar kemerleri az ve düz damarları (vasa recta) uzundur.',''],
['ileum','Ileum','İleum (kıvrım bağırsak)','İnce bağırsağın son beşte üçlük bölümüdür; B12 vitamini ve safra tuzları burada emilir. Lenf dokusu kümeleri (Peyer plakları) içerir.','B12 ve safra tuzu ileumda emilir'],
['hepatopancreatic ampulla','Ampulla hepatopancreatica','Hepatopankreatik ampulla (Vater ampullası)','Ductus choledochus ile ductus pancreaticus\'un birleşerek oluşturduğu genişlemedir; papilla duodeni major\'da duodenuma açılır. Buraya takılan safra taşı hem sarılığa hem pankreatite yol açabilir.',''],
['dorsal pancreatic duct','Ductus pancreaticus accessorius','Dorsal pankreas kanalı (Santorini kanalı)','Embriyodaki dorsal pankreas tomurcuğunun kanalıdır; uç bölümü ana kanala katılır, duodenuma yakın bölümü ise aksesuar kanal olarak papilla duodeni minor\'a açılır. İki tomurcuğun kanalları birleşmezse pancreas divisum olur.',''],
['common bile duct','Ductus choledochus','Koledok (ana safra kanalı)','Ductus hepaticus communis ile ductus cysticus\'un birleşmesiyle oluşur; lig. hepatoduodenale içinde iner, pankreas başının arkasından geçip duodenuma açılır. Pankreas başı tümörü basarsa ağrısız sarılık olur.',''],
['ventral pancreatic duct','Ductus pancreaticus','Ventral pankreas kanalı (Wirsung kanalı)','Embriyodaki ventral pankreas tomurcuğunun kanalıdır; erişkinde ana pankreas kanalının duodenuma yakın bölümünü oluşturur ve koledokla birlikte papilla duodeni major\'a açılır.','Wirsung = ana, Santorini = aksesuar'],
['gastric impression of liver','Impressio gastrica hepatis','Karaciğerin mide izi','Sol lobun alt (visseral) yüzünde midenin oluşturduğu çukurluktur.',''],
['suprarenal impression of liver','Impressio suprarenalis hepatis','Karaciğerin böbrek üstü bezi izi','Sağ lobun arka-alt yüzünde, sağ böbrek üstü bezinin oluşturduğu izdir; area nuda yakınındadır.',''],
['renal impression of liver','Impressio renalis hepatis','Karaciğerin böbrek izi','Sağ lobun alt yüzünde sağ böbreğin oluşturduğu çukurluktur. Karaciğer ile sağ böbrek arasındaki periton aralığı (Morison poşu) sırtüstü yatan hastada sıvının ilk toplandığı yerdir.',''],
['duodenal impression of liver','Impressio duodenalis hepatis','Karaciğerin duodenum izi','Sağ lobun alt yüzünde, safra kesesinin yanında duodenumun üst bölümünün oluşturduğu izdir.',''],
["esophageal impression of liver", "Impressio oesophagea hepatis", "Karaciğerin yemek borusu izi", "Sol lobun arka yüzünde yemek borusunun karın bölümünün oluşturduğu oluktur.", ""],
['porta hepatis','Porta hepatis','Karaciğer kapısı','Karaciğerin alt yüzündeki enine yarıktır; v. portae hepatis ve a. hepatica propria girer, safra kanalları çıkar.','Kapıdan giren: ven ve arter; çıkan: safra'],
['colic impression of liver','Impressio colica hepatis','Karaciğerin kolon izi','Sağ lobun alt yüzünün ön bölümünde kolonun sağ kıvrımının oluşturduğu izdir.',''],
["capsule of the liver", "Tunica fibrosa hepatis", "Karaciğer kapsülü (Glisson kapsülü)", "Karaciğeri saran ince bağ dokusu kılıftır; kapıdan içeri girerek damar ve safra kanallarını sarar. Karaciğer hızla büyürse kapsülün gerilmesi sağ üst karın ağrısı yapar.", ""],
['bare area of liver','Area nuda hepatis','Karaciğerin çıplak alanı','Karaciğerin arka yüzünde peritonla örtülmeyen ve doğrudan diyaframa yapışan alandır; lig. coronarium yaprakları sınırlar.',''],
['diaphragmatic surface of liver','Facies diaphragmatica hepatis','Karaciğerin diyafram yüzü','Karaciğerin diyaframa bakan kubbe biçimli ön-üst yüzüdür; lig. falciforme bu yüze tutunur.',''],
['anterolateral segment','Segmentum anterius laterale','Karaciğerin ön-yan segmenti','Karaciğerin sekiz işlevsel (Couinaud) segmentinden biridir; her segmentin kendi portal ven dalı, arteri ve safra kanalı vardır, bu yüzden ayrı ayrı çıkarılabilir. Modeldeki adı: anterolateral segment (solda segment III, sağda segment VI ile uyumludur).',''],
['superomedial segment','Segmentum mediale sinistrum (pars superior)','Karaciğerin üst-iç segmenti (segment IVa)','Sol karaciğerin medial bölümünün üst parçasıdır; lig. falciforme\'nin sağında yer alır. Modeldeki adı: superomedial segment.',''],
['superomedial segment1','Segmentum mediale sinistrum (pars superior)','Karaciğerin üst-iç segmenti (ikinci parça)','Modelde üst-iç segmentin ikinci parçası olarak ayrılmış bölümdür; segment IV\'ün üst bölümüne karşılık gelir. Modeldeki adı: superomedial segment1.',''],
['inferomedial segment','Segmentum mediale sinistrum (pars inferior)','Karaciğerin alt-iç segmenti (segment IVb)','Sol karaciğerin medial bölümünün alt parçasıdır; alt yüzde lobus quadratus\'a karşılık gelir. Modeldeki adı: inferomedial segment.',''],
['quadrate lobe of liver','Lobus quadratus hepatis','Karaciğerin dörtgen lobu','Alt yüzde safra kesesi ile lig. teres hepatis arasındaki bölümdür. Görünüşte sağ loba aittir ama işlevsel olarak sol karaciğerin parçasıdır (segment IV).',''],
['anterosuperior segment','Segmentum posterius mediale dextrum','Karaciğerin ön-üst segmenti (segment VIII)','Sağ karaciğerin ön bölümünün üst parçasıdır; diyafram kubbesinin altındadır. Modeldeki adı: anterosuperior segment.',''],
['posteroinferior segment','Segmentum anterius laterale dextrum','Karaciğerin arka-alt segmenti (segment VI)','Sağ karaciğerin arka bölümünün alt parçasıdır; sağ böbrekle komşudur. Modeldeki adı: posteroinferior segment.',''],
['posterosuperior segment','Segmentum posterius laterale dextrum','Karaciğerin arka-üst segmenti (segment VII)','Sağ karaciğerin arka bölümünün üst parçasıdır; area nuda yakınındadır. Modeldeki adı: posterosuperior segment.',''],
['anteroinferior segment','Segmentum anterius mediale dextrum','Karaciğerin ön-alt segmenti (segment V)','Sağ karaciğerin ön bölümünün alt parçasıdır; safra kesesi yatağının sağındadır. Modeldeki adı: anteroinferior segment.',''],
['coronary ligament of liver','Ligamentum coronarium hepatis','Karaciğerin koroner bağı','Peritonun diyaframdan karaciğere atladığı yerdir; ön ve arka yaprakları area nuda\'yı çevreler.',''],
['falciform ligament','Ligamentum falciforme hepatis','Falsiform bağ (orak biçimli bağ)','Karaciğeri karın ön duvarına ve diyaframa bağlayan orak biçimli periton kıvrımıdır; serbest alt kenarında lig. teres hepatis bulunur. Dıştan bakışta sağ ve sol lobu ayırır.',''],
['triangular ligament of liver','Ligamentum triangulare hepatis','Karaciğerin üçgen bağı','Koroner bağın ön ve arka yapraklarının sağ ve sol uçlarda birleşmesiyle oluşur; karaciğeri diyaframa bağlar.',''],
['ligamentum venosum','Ligamentum venosum','Ligamentum venosum','Fetüste göbek veninin kanını karaciğeri atlatarak v. cava inferior\'a taşıyan ductus venosus\'un doğumdan sonraki bağ dokusu kalıntısıdır.','Ductus venosus → lig. venosum'],
['round ligament of liver','Ligamentum teres hepatis','Karaciğerin yuvarlak bağı','Fetüsteki v. umbilicalis\'in kapanmış kalıntısıdır; göbekten karaciğere, falsiform bağın serbest kenarında uzanır. Portal hipertansiyonda çevresindeki venler genişleyip göbek çevresinde caput medusae oluşturabilir.','V. umbilicalis → lig. teres hepatis'],
['hepatoduodenal ligament','Ligamentum hepatoduodenale','Hepatoduodenal bağ','Küçük omentumun serbest sağ kenarıdır; içinde koledok (sağda önde), a. hepatica propria (solda önde) ve v. portae (arkada) bulunur. Arkasında foramen omentale vardır; karaciğer kanamasında parmakla sıkıştırılır (Pringle manevrası).','Portal üçlü: koledok, arter, portal ven'],
['tail of pancreas','Cauda pancreatis','Pankreas kuyruğu','Pankreasın dalak hilusuna uzanan uç bölümüdür; lig. splenorenale içinde yer alır ve pankreasın periton içindeki tek bölümüdür. Langerhans adacıkları en yoğun buradadır.',''],
['body of pancreas','Corpus pancreatis','Pankreas gövdesi','Midenin arkasında, L1-L2 düzeyinde orta hattı çaprazlar; üst kenarı boyunca a. splenica, arkasında v. splenica seyreder.',''],
['uncinate process of pancreas','Processus uncinatus pancreatis','Pankreasın çengel çıkıntısı','Pankreas başının alttan sola uzanan çengel biçimli bölümüdür; a. ve v. mesenterica superior\'un arkasına geçer.',''],
['head of pancreas','Caput pancreatis','Pankreas başı','Duodenumun C biçimli kıvrımının içine oturur; koledok arkasından geçer. Baş tümörleri koledoğu sıkıştırarak ağrısız sarılık yapar.',''],
['neck of pancreas','Collum pancreatis','Pankreas boynu','Baş ile gövde arasındaki dar bölümdür; hemen arkasında v. mesenterica superior ile v. splenica birleşerek v. portae hepatis\'i oluşturur.','Portal ven pankreas boynunun arkasında doğar'],
// Üriner sistem
['kidney capsule','Capsula fibrosa renis','Böbrek kapsülü','Böbreği doğrudan saran ince, sağlam bağ dokusu kılıftır; dışında sırasıyla böbrek çevresi yağ dokusu ve böbrek fasyası (Gerota) bulunur.',''],
['hilum of kidney','Hilum renale','Böbrek hilusu (kapısı)','Böbreğin iç kenarındaki yarıktır; önden arkaya v. renalis, a. renalis ve pelvis renalis dizilir.','Önden arkaya: Ven, Arter, Pelvis (VAP)'],
['renal papilla','Papilla renalis','Böbrek papillası','Böbrek piramidinin kalikse bakan tepesidir; toplayıcı kanallar buradaki deliklerden idrarı küçük kalikse boşaltır.',''],
['renal pyramid','Pyramis renalis','Böbrek piramidi','Böbrek öz bölgesindeki (medulla) koni biçimli yapıdır; Henle kulpları ve toplayıcı kanalları içerir, idrarı tepesindeki papillaya taşır.',''],
['renal column','Columna renalis','Böbrek sütunu (Bertin sütunu)','Kabuk dokusunun piramitler arasına doğru inen uzantısıdır; içinden interlober damarlar geçer.',''],
['outer cortex of kidney','Cortex renalis','Böbrek kabuğu (korteks)','Böbreğin kapsül altındaki dış bölümüdür; böbrek cisimcikleri (glomerüller) ile kıvrımlı tübüller burada bulunur, kan burada süzülür.',''],
["minor calyx", "Calix renalis minor", "Küçük kaliks", "Bir böbrek papillasını saran ve ondan damlayan idrarı toplayan kadeh biçimli yapıdır; birkaçı birleşip büyük kaliksi oluşturur.", ""],
["major calyx", "Calix renalis major", "Büyük kaliks", "İki-üç küçük kaliksin birleşmesiyle oluşur; her böbrekte iki-üç tane bulunur ve pelvis renalis'e açılır.", ""],
['renal pelvis','Pelvis renalis','Böbrek pelvisi (havuzcuğu)','Büyük kalikslerin birleşmesiyle oluşan huni biçimli yapıdır; daralarak üretere devam eder. Üreter ile birleştiği yer taşların takıldığı üç darlıktan ilkidir.',''],
['fundus of urinary bladder','Fundus vesicae','Mesane tabanı (fundus)','Mesanenin arkaya-aşağıya bakan yüzüdür; kadında vajina ön duvarı ve serviks ile komşudur. Üreterler bu yüzün üst köşelerinden girer.',''],
["urinary bladder neck smooth muscle", "Musculus sphincter internus urethrae femininae (cervix vesicae)", "Mesane boynu düz kası (iç üretra sfinkteri)", "Mesane boynunda üretranın başlangıcını saran düz kastır; istem dışı çalışır ve sempatik uyarıyla kasılarak idrarı tutar. İstemli tutmayı çizgili dış sfinkter (n. pudendus) sağlar.", ""],
['trigone of urinary bladder','Trigonum vesicae','Mesane üçgeni (trigon)','İki üreter ağzı ile üretranın iç ağzı arasındaki üçgen alandır; mukozası mesane boşken de düzdür, kıvrım yapmaz. Embriyoda mezonefrik kanallardan (mezoderm) gelişir.','Üçgenin köşeleri: 2 üreter ağzı + 1 üretra ağzı'],
['ureteral orifice','Ostium ureteris','Üreter ağzı','Üreterin mesaneye açıldığı yarık biçimli deliktir. Üreter mesane duvarından eğik geçtiği için mesane doldukça kapanır ve idrarın geri kaçması (reflü) önlenir.',''],
// Kalp
['interventricular septum','Septum interventriculare','Ventriküller arası bölme','Sağ ve sol ventrikülü ayırır; büyük bölümü kalın kas, üst küçük bölümü ince zardır. En sık doğumsal kalp hastalığı olan ventriküler septal defekt çoğunlukla zar bölümündedir. Ön 2/3\'ünü sol ön inen arter besler.',''],
['cardiac atrium','Atrium cordis','Atriyum','Kalbin kanı toplayan üst boşluğudur. Sağ atriyum vücuttan gelen kanı (v. cava superior, v. cava inferior, sinus coronarius), sol atriyum akciğerlerden gelen kanı (dört pulmoner ven) alır.',''],
['heart ventricle','Ventriculus cordis','Ventrikül','Kalbin kanı pompalayan alt boşluğudur. Sağ ventrikül kanı truncus pulmonalis ile akciğerlere, sol ventrikül aorta ile bütün vücuda gönderir; sol ventrikülün duvarı yaklaşık üç kat daha kalındır.',''],
['aortic valve','Valva aortae','Aort kapağı','Sol ventrikül ile aorta arasındaki üç yarım ay yaprakçıklı kapaktır; sağ ve sol yaprakçıkların üstündeki sinüslerden koroner arterler çıkar. Sağ 2. kaburga arasında, göğüs kemiği kenarında dinlenir.',''],
['pulmonary valve','Valva trunci pulmonalis','Pulmoner kapak','Sağ ventrikül ile truncus pulmonalis arasındaki üç yarım ay yaprakçıklı kapaktır. Sol 2. kaburga arasında, göğüs kemiği kenarında dinlenir.',''],
['mitral valve','Valva mitralis (valva atrioventricularis sinistra)','Mitral kapak','Sol atriyum ile sol ventrikül arasındaki iki yaprakçıklı kapaktır; yaprakçıkları chordae tendineae ile papiller kaslara bağlıdır. Kalp tepesinde (sol 5. kaburga arası, orta köprücük çizgisi) dinlenir.','Mitral = 2 yaprakçık, sol taraf'],
['tricuspid valve','Valva tricuspidalis (valva atrioventricularis dextra)','Triküspit kapak','Sağ atriyum ile sağ ventrikül arasındaki üç yaprakçıklı kapaktır. Göğüs kemiğinin alt ucunun yanında dinlenir; damar yoluyla madde kullananlarda enfeksiyonu (endokardit) sıktır.','Tri = 3 yaprakçık, sağ taraf'],
// Damarlar
['uterine artery','Arteria uterina','Uterus arteri','A. iliaca interna\'nın dalıdır; kardinal bağ içinde ilerler ve serviksin yaklaşık 2 santimetre yanında üreterin üstünden çaprazlar. Histerektomide arter bağlanırken üreter zedelenebilir.','Su köprünün altından akar: üreter altta, a. uterina üstte'],
["uterine vein", "Venae uterinae", "Uterus veni", "Uterus çevresindeki ven ağından (plexus venosus uterinus) kanı toplar ve v. iliaca interna'ya döker.", ""],
['ophthalmic vein','Venae ophthalmicae','Göz venleri','Göz küresi ve göz çukurunun kanını toplayan venlerdir; üst ve alt olmak üzere iki ana ven bulunur ve kan esas olarak sinus cavernosus\'a boşalır.',''],
['superior ophthalmic vein','Vena ophthalmica superior','Üst göz veni','Göz çukurunun ana venidir; fissura orbitalis superior\'dan geçip sinus cavernosus\'a dökülür. Yüz venleriyle bağlantılı olduğundan yüz enfeksiyonları bu yolla kafa içine yayılabilir.',''],
['inferior ophthalmic vein','Vena ophthalmica inferior','Alt göz veni','Göz çukurunun tabanındaki ven ağından başlar; üst göz venine ya da sinus cavernosus\'a dökülür, fissura orbitalis inferior yoluyla plexus pterygoideus ile de bağlantı kurar.',''],
['central retinal vein','Vena centralis retinae','Retinanın merkezi veni','Retinanın kanını toplar; n. opticus içinde merkezi arterle birlikte ilerler ve üst göz venine ya da sinus cavernosus\'a dökülür. Tıkanmasında ani, ağrısız görme kaybı ve yaygın retina kanamaları görülür.',''],
['long posterior ciliary artery','Arteriae ciliares posteriores longae','Uzun arka siliyer arter','A. ophthalmica\'nın dalıdır; iki tanedir. Sklerayı n. opticus yakınında delip öne ilerler, siliyer cismi ve irisi besler.',''],
['central retinal artery','Arteria centralis retinae','Retinanın merkezi arteri','A. ophthalmica\'nın ilk dalıdır; n. opticus içinden geçerek retinanın iç katlarını besler. Uç arter olduğu için tıkanması ani, ağrısız körlüğe yol açar; göz dibinde kiraz kırmızısı leke görülür.','Uç arter: tıkanırsa yedeği yok'],
['inferior rectal vein','Venae rectales inferiores','Alt rektum venleri','Anal kanalın alt bölümünün kanını v. pudenda interna\'ya taşır (sistemik dolaşım). Dış hemoroidler bu venlerin genişlemesidir ve ağrılıdır.',''],
['middle rectal vein','Venae rectales mediae','Orta rektum venleri','Rektumun orta bölümünün kanını v. iliaca interna\'ya taşır. Üst rektum veni portal sisteme döküldüğü için rektum önemli bir portal-sistemik bağlantı (portokaval anastomoz) yeridir.','Üst rektal ven portal, orta ve alt sistemik'],
['inferior pancreaticoduodenal vein','Venae pancreaticoduodenales inferiores','Alt pankreatikoduodenal ven','Pankreas başı ve duodenumun alt bölümünün kanını v. mesenterica superior\'a taşır.',''],
['cystic artery','Arteria cystica','Safra kesesi arteri','Çoğunlukla a. hepatica propria\'nın sağ dalından çıkar ve Calot üçgeni (ductus cysticus, ductus hepaticus communis ve karaciğer alt yüzü arası) içinde bulunur. Kolesistektomide bu üçgende bulunup bağlanır.','Calot üçgeninde a. cystica aranır'],
["cystic vein", "Venae cysticae", "Safra kesesi veni", "Safra kesesinin kanını çoğunlukla v. portae hepatis'in sağ dalına ya da doğrudan karaciğer içine taşır.", ""],
["middle hepatic artery branch of hepatic artery", "Ramus intermedius arteriae hepaticae sinistrae", "Orta hepatik arter", "A. hepatica propria'nın sağ ya da sol dalından çıkan ve karaciğerin medial bölümünü (segment IV, lobus quadratus) besleyen daldır.", ""],
['hepatic artery','Arteria hepatica propria','Hepatik arter','Truncus coeliacus\'un dalı olan a. hepatica communis\'ten gelir; lig. hepatoduodenale içinde yükselip sağ ve sol dala ayrılır. Karaciğere gelen kanın yaklaşık dörtte birini taşır, kalanı portal venden gelir.',''],
['posterior segmental hepatic artery','Arteria segmenti posterioris hepatis','Karaciğerin arka segment arteri','A. hepatica propria\'nın sağ dalından çıkar; sağ karaciğerin arka bölümünü (segment VI ve VII) besler.',''],
['anterior segmental hepatic artery','Arteria segmenti anterioris hepatis','Karaciğerin ön segment arteri','A. hepatica propria\'nın sağ dalından çıkar; sağ karaciğerin ön bölümünü (segment V ve VIII) besler.',''],
['branch of portal vein','Rami venae portae hepatis','Portal ven dalı','V. portae hepatis karaciğer kapısında sağ ve sol dala ayrılır; dallar sindirim kanalı ve dalaktan gelen besin yüklü kanı karaciğer segmentlerine dağıtır. Karaciğer segmentleri bu dallanmaya göre tanımlanır.',''],
['great vein of heart','Vena cardiaca magna','Kalbin büyük veni','Ön ventriküller arası olukta sol ön inen arterle birlikte yükselir, sonra koroner olukta sola dönerek sinus coronarius\'a devam eder.',''],
['oblique vein of atrium','Vena obliqua atrii sinistri','Sol atriyumun eğik veni (Marshall veni)','Sol atriyumun arka yüzünde inip sinus coronarius\'a açılan küçük vendir; embriyodaki sol vena cava superior\'un kalıntısıdır.',''],
["anterior descending branch of pulmonary artery", "Ramus descendens arteriae segmentalis anterioris", "Pulmoner arterin ön inen dalı", "Pulmoner arterin üst loba giden dallarından biridir; üst lobun ön bölümüne oksijeni azalmış kan taşır. Modeldeki adı: anterior descending branch of pulmonary artery.", ""],
['coronary artery','Arteriae coronariae','Koroner arter','Kalp kasını besleyen arterlerdir; sağ ve sol koroner arter aort kapağının hemen üstündeki sinüslerden çıkar ve kalp gevşerken (diyastolde) dolar. Tıkanmaları kalp krizine (miyokard enfarktüsü) yol açar; en sık tıkanan dal sol ön inen arterdir.','Koronerler diyastolde dolar'],
['marginal artery','Ramus marginalis','Marjinal dal (kenar arteri)','Kalbin kenarı boyunca ilerleyen koroner dalıdır: sağ koroner arterden çıkan ramus marginalis dexter sağ ventrikülü, a. circumflexa\'dan çıkan ramus marginalis sinister sol ventrikülün yan duvarını besler.',''],
["posterior descending branch of circumflex branch of coronary artery", "Ramus interventricularis posterior arteriae circumflexae cordis", "Sirkumfleks arterin arka inen dalı", "Arka ventriküller arası olukta ilerler; septumun arka 1/3'ünü ve ventriküllerin alt duvarını besler. Bu dal insanların çoğunda sağ koroner arterden çıkar (sağ baskınlık); sirkumfleksten çıkması sol baskınlık olarak adlandırılır.", "Arka inen dalı kim veriyorsa baskın odur"],
['posterior ventricular branch of circumflex coronary artery','Ramus posterior ventriculi sinistri','Sirkumfleks arterin sol ventrikül arka dalı','A. circumflexa\'dan çıkar ve sol ventrikülün arka duvarını besler.',''],
['common carotid artery plus branches','Arteria carotis communis','Ana karotis arter (a. carotis communis) ve dalları','Sağda truncus brachiocephalicus\'tan, solda doğrudan aort yayından çıkar; tiroit kıkırdağın üst kenarı (C4) düzeyinde a. carotis interna ve externa\'ya ayrılır. Ayrım yerinde basınç algılayan sinus caroticus ve kandaki oksijeni algılayan glomus caroticum bulunur.','İnterna boyunda dal vermez, eksterna verir'],
// Solunum sistemi
['lung hilus','Hilum pulmonis','Akciğer hilusu (kapısı)','Akciğerin iç yüzünde ana bronş, a. pulmonalis, pulmoner venler, lenf düğümleri ve sinirlerin girip çıktığı yerdir. A. pulmonalis sağda bronşun önünde, solda bronşun üstündedir.','RALS: Right Anterior, Left Superior (arterin bronşa göre yeri)'],
['superior lingular bronchopulmonary segment','Segmentum lingulare superius [S IV]','Üst lingula segmenti','Sol akciğer üst lobunun lingula bölümünün üst segmentidir. Her bronkopulmoner segmentin kendi bronşu ve arteri vardır; bu yüzden tek başına çıkarılabilir.',''],
['anterior bronchopulmonary segment','Segmentum anterius [S III]','Ön segment (üst lob)','Akciğer üst lobunun öne bakan segmentidir; iki akciğerde de bulunur.',''],
['apical bronchopulmonary segment','Segmentum apicale [S I]','Tepe (apikal) segment','Üst lobun akciğer tepesini oluşturan segmentidir; solda arka segmentle birleşiktir (apikoposterior segment). Tüberkülozun yeniden alevlenmesi en sık tepe bölgesinde görülür.',''],
['posterior bronchopulmonary segment','Segmentum posterius [S II]','Arka segment (üst lob)','Üst lobun arkaya bakan segmentidir. Sırtüstü yatan hastada solunum yoluna kaçan içerik sağ üst lobun arka segmentine gidebilir.',''],
['inferior lingular bronchopulmonary segment','Segmentum lingulare inferius [S V]','Alt lingula segmenti','Sol akciğer üst lobunun lingula bölümünün alt segmentidir; kalbin sol kenarına komşudur.',''],
['superior bronchopulmonary segment','Segmentum superius [S VI]','Alt lobun üst (apikal) segmenti','Alt lobun en üstteki segmentidir. Sırtüstü yatan hastada solunum yoluna kaçan içerik en sık sağ alt lobun bu segmentine gider.',''],
['posterior basal bronchopulmonary segment','Segmentum basale posterius [S X]','Arka bazal segment','Alt lobun tabanındaki arka segmenttir. Ayakta ya da oturan hastada solunum yoluna kaçan içerik en sık sağ alt lobun bazal segmentlerine gider.',''],
['anterior basal bronchopulmonary segment','Segmentum basale anterius [S VIII]','Ön bazal segment','Alt lobun tabanındaki ön segmenttir; diyafram üzerine oturur.',''],
['lateral basal bronchopulmonary segment','Segmentum basale laterale [S IX]','Yan (lateral) bazal segment','Alt lobun tabanındaki dış yan segmenttir; diyafram üzerine oturur.',''],
['medial basal bronchopulmonary segment','Segmentum basale mediale [S VII]','İç (medial) bazal segment','Alt lobun tabanındaki iç segmenttir; kalbe komşu olduğu için kardiyak segment de denir. Solda çoğunlukla ön bazal segmentle birleşiktir.',''],
['medial bronchopulmonary segment','Segmentum mediale [S V]','Orta lobun iç (medial) segmenti','Sağ akciğer orta lobunun kalbe komşu iç segmentidir.',''],
['lateral bronchopulmonary segment','Segmentum laterale [S IV]','Orta lobun dış (lateral) segmenti','Sağ akciğer orta lobunun dış yan segmentidir.',''],
['epiglottic cartilage','Cartilago epiglottica','Epiglot kıkırdağı','Yaprak biçimli elastik kıkırdaktır; yutma sırasında gırtlak girişinin üstüne kapanarak besinlerin soluk yoluna kaçmasını önler.',''],
['trachea cartilage','Cartilagines tracheales','Soluk borusu kıkırdakları','Soluk borusunu açık tutan 16-20 adet C biçimli hiyalin kıkırdak halkadır; açık arka bölümlerini düz kas (m. trachealis) kapatır, böylece arkadaki yemek borusu lokma geçerken genişleyebilir.',''],
['carina of trachea','Carina tracheae','Karina (trakea mahmuzu)','Soluk borusunun iki ana bronşa ayrıldığı yerdeki iç çıkıntıdır; T4-T5 (angulus sterni) düzeyindedir. Mukozası çok duyarlıdır, dokunulunca güçlü öksürük refleksi başlar.','Karina = angulus sterni düzeyi (T4-T5)'],
['cartilage of main bronchus','Cartilagines bronchiales (bronchus principalis)','Ana bronş kıkırdağı','Ana bronşu açık tutan C biçimli kıkırdak halkalardır. Sağ ana bronş daha geniş, kısa ve dik olduğundan yabancı cisimler daha çok sağa kaçar.','Yabancı cisim sağa kaçar'],
['cartilage of lobar bronchus','Cartilagines bronchiales (bronchus lobaris)','Lob bronşu kıkırdağı','Lob bronşlarının duvarındaki kıkırdak plaklardır; akciğer içinde halkaların yerini düzensiz plaklar alır.',''],
['cartilage of segmental bronchus','Cartilagines bronchiales (bronchus segmentalis)','Segment bronşu kıkırdağı','Segment bronşlarının duvarındaki küçük kıkırdak plaklardır; bronşlar inceldikçe azalır ve bronşiyollerde kıkırdak hiç bulunmaz.','Bronşiyolde kıkırdak yok'],
['lobar bronchus of lung upper lobe','Bronchus lobaris superior','Üst lob bronşu','Ana bronştan ayrılıp akciğerin üst lobuna giden bronştur. Sağ üst lob bronşu a. pulmonalis\'in üstünden çıkar (eparteriyel bronş).',''],
['lobar bronchus of lung lower lobe','Bronchus lobaris inferior','Alt lob bronşu','Ana bronşun devamı olarak alt loba giden bronştur; üst segment ve bazal segment bronşlarına ayrılır.',''],
['anterior basal segmental bronchus','Bronchus segmentalis basalis anterior [B VIII]','Ön bazal segment bronşu','Alt lobun ön bazal segmentine hava taşır.',''],
['superior lingular bronchus','Bronchus lingularis superior [B IV]','Üst lingula bronşu','Sol üst lobun üst lingula segmentine hava taşır.',''],
['apical segmental bronchus','Bronchus segmentalis apicalis [B I]','Tepe (apikal) segment bronşu','Üst lobun tepe segmentine hava taşır; solda arka segment bronşuyla ortak gövdeden çıkar.',''],
['posterior basal segmental bronchus','Bronchus segmentalis basalis posterior [B X]','Arka bazal segment bronşu','Alt lobun arka bazal segmentine hava taşır.',''],
['medial basal segmental bronchus','Bronchus segmentalis basalis medialis [B VII]','İç (medial) bazal segment bronşu','Alt lobun kalbe komşu iç bazal segmentine hava taşır.',''],
['superior segmental bronchus','Bronchus segmentalis superior [B VI]','Alt lobun üst segment bronşu','Alt lob bronşunun arkaya doğru verdiği ilk daldır; alt lobun üst segmentine hava taşır.',''],
['anterior segmental bronchus','Bronchus segmentalis anterior [B III]','Ön segment bronşu','Üst lobun ön segmentine hava taşır.',''],
['posterior segmental bronchus','Bronchus segmentalis posterior [B II]','Arka segment bronşu','Üst lobun arka segmentine hava taşır.',''],
['lateral basal segmental bronchus','Bronchus segmentalis basalis lateralis [B IX]','Yan (lateral) bazal segment bronşu','Alt lobun dış yan bazal segmentine hava taşır.',''],
['inferior lingular bronchus','Bronchus lingularis inferior [B V]','Alt lingula bronşu','Sol üst lobun alt lingula segmentine hava taşır.',''],
['middle lobar bronchus','Bronchus lobaris medius','Orta lob bronşu','Sağ akciğerin orta lobuna giden bronştur; iç ve dış segment bronşlarına ayrılır. Dar ve çevresi lenf düğümleriyle sarılı olduğundan kolay tıkanır (orta lob sendromu).',''],
['superior lobar bronchus','Bronchus lobaris superior','Üst lob bronşu','Akciğerin üst lobuna giden bronştur; sağda tepe, arka ve ön segment bronşlarına, solda ayrıca lingula bronşlarına ayrılır.',''],
['inferior lobar bronchus','Bronchus lobaris inferior','Alt lob bronşu','Akciğerin alt lobuna giden bronştur; üst segment bronşu ile bazal segment bronşlarını verir.',''],
['lateral segmental bronchus','Bronchus segmentalis lateralis [B IV]','Orta lobun dış (lateral) segment bronşu','Sağ akciğer orta lobunun dış segmentine hava taşır.',''],
['medial segmental bronchus','Bronchus segmentalis medialis [B V]','Orta lobun iç (medial) segment bronşu','Sağ akciğer orta lobunun iç segmentine hava taşır.',''],
// Lenf sistemi
['gastric surface of spleen','Facies gastrica splenis','Dalağın mide yüzü','Dalağın iç (visseral) yüzünün hilus önünde kalan, mideye komşu bölümüdür.',''],
['diaphragmatic surface of spleen','Facies diaphragmatica splenis','Dalağın diyafram yüzü','Dalağın diyaframa bakan dışbükey yüzüdür; sol 9-11. kaburgalarla komşudur. Bu kaburgaların kırıklarında dalak yırtılabilir.','Dalak: 9-10-11. kaburgalar'],
['colic surface of spleen','Facies colica splenis','Dalağın kolon yüzü','Dalağın alt ucunda, kolonun sol kıvrımına komşu yüzüdür.',''],
['hilum of spleen','Hilum splenicum','Dalak hilusu (kapısı)','Dalağın iç yüzünde a. ve v. splenica dallarının girip çıktığı yarıktır; pankreas kuyruğu buraya kadar uzanır.',''],
['renal surface of spleen','Facies renalis splenis','Dalağın böbrek yüzü','Dalağın iç yüzünün hilus arkasında kalan, sol böbreğe komşu bölümüdür.',''],
['thymus lobe','Lobus thymi','Timus lobu','Timus üst-ön mediastende, göğüs kemiğinin arkasındaki iki loblu organdır; T lenfositler burada olgunlaşır. Çocuklukta büyüktür, ergenlikten sonra küçülüp yağ dokusuna dönüşür.','T lenfosit = Timus'],
['afferent lymphatic vessel','Vas lymphaticum afferens','Getirici lenf damarı','Lenfi lenf düğümüne getiren damardır; birden çok sayıdadır ve düğümün dışbükey yüzünden kapsülü delerek girer.','Afferent çok ve getirir, efferent az ve götürür'],
['capsule of lymph node','Capsula nodi lymphoidei','Lenf düğümü kapsülü','Lenf düğümünü saran bağ dokusu kılıftır; içeri uzanan bölmeleri (trabeküller) düğümü kompartmanlara ayırır. Lenf önce kapsül altındaki sinüse dökülür.',''],
["lymph node follicle", "Nodulus lymphoideus", "Lenf folikülü", "Lenf düğümünün dış korteksindeki yuvarlak B lenfosit kümesidir. Antijenle karşılaşınca ortasında B hücrelerinin çoğaldığı germinal merkez oluşur.", "Folikül = B hücresi"],
['efferent lymphatic vessel','Vas lymphaticum efferens','Götürücü lenf damarı','Süzülmüş lenfi lenf düğümünden çıkaran damardır; az sayıdadır ve hilustan çıkar.',''],
['medulla of lymph node','Medulla nodi lymphoidei','Lenf düğümü medullası (öz bölgesi)','Lenf düğümünün hilusa yakın iç bölümüdür; antikor salgılayan plazma hücrelerinden zengin kordonlar ve lenfin aktığı sinüslerden oluşur.',''],
['lymph node t cell domain','Paracortex nodi lymphoidei','Lenf düğümü parakorteksi (T hücre bölgesi)','Foliküller ile medulla arasındaki bölgedir; T lenfositler ve onlara antijen sunan dendritik hücreler burada bulunur. Kandaki lenfositler düğüme buradaki yüksek endotelli venüllerden girer.','Parakorteks = T hücresi'],
['lymph vasculature','Vasa lymphatica','Lenf damarları','Doku aralarındaki fazla sıvıyı ve bağırsaktan emilen yağları toplayıp venöz dolaşıma geri taşıyan damar ağıdır. Vücudun büyük bölümünün lenfi ductus thoracicus ile sol venöz açıya, sağ üst çeyreğin lenfi sağ venöz açıya dökülür.',''],
// İskelet
['fused sacrum','Os sacrum','Sakrum (sağrı kemiği)','Beş sakral omurun kaynaşmasıyla oluşan üçgen kemiktir; iki kalça kemiği arasına oturarak gövde ağırlığını pelvise aktarır. Sakral sinirler ön ve arka deliklerinden çıkar.',''],
['coccyx','Os coccygis','Koksiks (kuyruk kemiği)','Üç-beş küçük omurun kaynaşmasıyla oluşan omurganın son parçasıdır; pelvis tabanı kasları ve bağları için tutunma yeridir.',''],
['trabecular bone tissue','Substantia spongiosa','Süngerimsi kemik dokusu','Kemiğin iç bölümündeki ince kemik çubuklarından (trabekül) oluşan gözenekli dokudur; aralarını kemik iliği doldurur. Trabeküller yük çizgileri boyunca dizilir; osteoporozda en erken bu doku azalır.',''],
['compact bone tissue','Substantia compacta','Sıkı (kompakt) kemik dokusu','Kemiğin dış bölümündeki yoğun dokudur; iç içe halkalar biçimindeki osteonlardan (Havers sistemi) oluşur ve kemiğe sağlamlığını verir.',''],
['tibial collateral ligament','Ligamentum collaterale tibiale','Dizin iç yan bağı (medial kollateral bağ)','Femurun iç epikondilinden tibiaya uzanır; dizin içe doğru açılmasını (valgus zorlaması) önler. İç menisküse yapışık olduğundan ikisi çoğu kez birlikte yaralanır.','Mutsuz üçlü: iç yan bağ + ön çapraz bağ + menisküs'],
['anterior cruciate ligament','Ligamentum cruciatum anterius','Ön çapraz bağ','Tibianın ön interkondiler alanından femurun dış kondilinin iç yüzüne uzanır; tibianın femura göre öne kaymasını önler. Yırtığında ön çekmece ve Lachman testleri pozitiftir.','Ön çapraz bağ = ön çekmece testi'],
['posterior cruciate ligament','Ligamentum cruciatum posterius','Arka çapraz bağ','Tibianın arka interkondiler alanından femurun iç kondilinin dış yüzüne uzanır; tibianın arkaya kaymasını önler. Ön çapraz bağdan daha kalın ve güçlüdür; diz bükülüyken tibiaya önden gelen darbeyle yırtılır.','Arka çapraz bağ = arka çekmece testi'],
['anterolateral ligament of knee','Ligamentum anterolaterale genus','Dizin ön-dış bağı','Femurun dış epikondilinden tibianın ön-dış bölümüne uzanan ince bağdır; tibianın içe dönmesini sınırlar ve çoğunlukla ön çapraz bağ ile birlikte yaralanır.',''],
['fibular collateral ligament','Ligamentum collaterale fibulare','Dizin dış yan bağı (lateral kollateral bağ)','Femurun dış epikondilinden fibula başına uzanan kordon biçimli bağdır; dizin dışa doğru açılmasını (varus zorlaması) önler. Dış menisküse yapışık değildir.',''],
['patellar ligament','Ligamentum patellae','Patella bağı','Kuadriseps tendonunun patelladan tuberositas tibiae\'ye uzanan devamıdır. Patella refleksi bu bağa vurularak alınır (L3-L4).',''],
['articular disk of knee joint','Meniscus (medialis et lateralis)','Menisküs','Tibia kondilleri üzerindeki yarım ay biçimli lifli kıkırdak yastıklardır; eklem yüzlerini uyumlu hale getirir ve yükü dağıtır. İç menisküs C biçimli ve daha az hareketli olduğundan daha sık yırtılır. Modeldeki adı: articular disk of knee joint.','İç menisküs C, dış menisküs O biçimli'],
['patellar surface of femur','Facies patellaris femoris','Femurun patella yüzü','Femurun alt ucunun ön yüzünde, iki kondil arasındaki oluk biçimli eklem yüzüdür; patella diz hareketlerinde bu olukta kayar.',''],
['medial perichondular surface','Facies perichondralis medialis','Femur iç kondilinin kıkırdak kenarı yüzeyi','Femurun alt ucunda eklem kıkırdağının iç kenarını çevreleyen yüzeydir; eklem kapsülü ve sinovyal zar bu kenara tutunur. Modeldeki adı: medial perichondular surface.',''],
['articular cartilage of distal epiphysis of femur','Cartilago articularis epiphysis distalis femoris','Femur alt ucunun eklem kıkırdağı','Femur kondillerini ve patella yüzünü örten hiyalin kıkırdaktır; sürtünmeyi azaltır ve yükü dağıtır. Damarsız olduğu için sinovyal sıvıdan beslenir ve zor iyileşir; aşınması diz kireçlenmesine (gonartroz) yol açar.',''],
['medial condyle of femur','Condylus medialis femoris','Femurun iç kondili','Femurun alt ucundaki iç eklem çıkıntısıdır; tibianın iç kondili ile eklem yapar. Dış kondile göre daha uzun ve dardır.',''],
['lateral condyle of femur','Condylus lateralis femoris','Femurun dış kondili','Femurun alt ucundaki dış eklem çıkıntısıdır; tibianın dış kondili ile eklem yapar. Öne doğru daha çıkıntılıdır ve patellanın dışa kaymasını önler.',''],
['distal-most point of medial condyle of femur','Punctum distalissimum condyli medialis femoris','Femur iç kondilinin en alt noktası','Femurun iç kondilinin en aşağıdaki noktasıdır; anatomik bir yapı değil, ölçüm ve hizalama için kullanılan işaret noktasıdır. Modeldeki adı: distal-most point of medial condyle of femur.',''],
['intercondylar fossa of femur','Fossa intercondylaris femoris','Femurun kondiller arası çukuru','Femur kondilleri arasında arkadaki derin çukurdur; çapraz bağlar bu çukurun yan duvarlarına tutunur.',''],
['posterior cruciate enthesis','Insertio ligamenti cruciati posterioris','Arka çapraz bağın tutunma yeri','Arka çapraz bağın femurda iç kondilin kondiller arası çukura bakan yüzüne tutunduğu alandır. Entezis, bağ ya da kirişin kemiğe yapıştığı yer demektir. Modeldeki adı: posterior cruciate enthesis.',''],
['anterior cruciate enthesis','Insertio ligamenti cruciati anterioris','Ön çapraz bağın tutunma yeri','Ön çapraz bağın femurda dış kondilin kondiller arası çukura bakan yüzüne tutunduğu alandır. Modeldeki adı: anterior cruciate enthesis.',''],
['lateral perichondular surface','Facies perichondralis lateralis','Femur dış kondilinin kıkırdak kenarı yüzeyi','Femurun alt ucunda eklem kıkırdağının dış kenarını çevreleyen yüzeydir; eklem kapsülü ve sinovyal zar bu kenara tutunur. Modeldeki adı: lateral perichondular surface.',''],
['lateral epicondylar enthesis','Insertio epicondyli lateralis femoris','Femur dış epikondilindeki tutunma yeri','Dizin dış yan bağının femurun dış epikondiline tutunduğu alandır. Modeldeki adı: lateral epicondylar enthesis.',''],
['medial epicondylar enthesis','Insertio epicondyli medialis femoris','Femur iç epikondilindeki tutunma yeri','Dizin iç yan bağının femurun iç epikondiline tutunduğu alandır. Modeldeki adı: medial epicondylar enthesis.',''],
['lumbar vertebra 1','Vertebra lumbalis I','1. bel omuru (L1)','Bel omurlarının ilkidir. Erişkinde omurilik bu omurun alt kenarı (L1-L2) düzeyinde conus medullaris ile sonlanır; pilor ve pankreas boynu da bu düzeydedir.','Omurilik L1-L2\'de biter'],
['lumbar vertebra 2','Vertebra lumbalis II','2. bel omuru (L2)','Gövdesi büyük, böbrek biçimli tipik bel omurudur; kaburga eklem yüzü ve enine çıkıntı deliği yoktur. Diyaframın sağ bacağı ilk üç bel omuruna tutunur.',''],
['lumbar vertebra 3','Vertebra lumbalis III','3. bel omuru (L3)','Tipik bel omurudur; enine çıkıntıları en uzun olandır. Duodenumun yatay bölümü bu omurun önünden geçer.',''],
['lumbar vertebra 4','Vertebra lumbalis IV','4. bel omuru (L4)','İki kalça kemiği tarağının en üst noktalarını birleştiren çizgi bu omurun dikensi çıkıntısından geçer. Bel ponksiyonu L3-L4 ya da L4-L5 aralığından yapılır; aorta bu düzeyde ikiye ayrılır.','Kalça tarakları çizgisi = L4; ponksiyon L3-L4 ya da L4-L5'],
['lumbar vertebra 5','Vertebra lumbalis V','5. bel omuru (L5)','En büyük bel omurudur; gövdesi önde daha yüksektir ve sakrumla açı yapar. Sakrum üzerinde öne kayması (spondilolistezis) en sık bu düzeydedir.',''],
["lumbar vertebra 6", "Vertebra lumbalis VI", "6. bel omuru (varyasyon)", "Normalde beş bel omuru bulunur. Altıncı bel omuru, birinci sakral omurun sakruma kaynaşmayıp serbest kalmasıyla (lumbalizasyon) ortaya çıkan bir geçiş omurudur. Modeldeki adı: lumbar vertebra 6.", ""],
['thoracic vertebra 1','Vertebra thoracica I','1. sırt omuru (T1)','Sırt omurlarının ilkidir; gövdesinde 1. kaburga için tam, 2. kaburga için yarım eklem yüzü bulunur. Dikensi çıkıntısı uzundur ve C7 gibi ensede ele gelir.',''],
['thoracic vertebra 2','Vertebra thoracica II','2. sırt omuru (T2)','Tipik sırt omurudur; gövdesinin yanlarında kaburga başları, enine çıkıntısında kaburga tümseği için eklem yüzleri bulunur.',''],
['thoracic vertebra 3','Vertebra thoracica III','3. sırt omuru (T3)','Tipik sırt omurudur; kürek kemiği dikeninin iç ucu bu omurun dikensi çıkıntısı düzeyindedir.',''],
['thoracic vertebra 4','Vertebra thoracica IV','4. sırt omuru (T4)','T4-T5 arasındaki disk angulus sterni ile aynı yatay düzlemdedir; bu düzlemde soluk borusu ikiye ayrılır, aort yayı başlar ve biter.','Angulus sterni = T4-T5 = karina'],
['thoracic vertebra 5','Vertebra thoracica V','5. sırt omuru (T5)','Tipik sırt omurudur; gövdesi yürek biçimli, dikensi çıkıntısı uzun ve aşağı eğiktir. Kaburgalarla eklem yaparak göğüs kafesini oluşturur.',''],
['thoracic vertebra 6','Vertebra thoracica VI','6. sırt omuru (T6)','Tipik sırt omurudur; kaburga başları ve tümsekleri için eklem yüzleri taşır.',''],
['thoracic vertebra 7','Vertebra thoracica VII','7. sırt omuru (T7)','Tipik sırt omurudur; kürek kemiğinin alt açısı yaklaşık olarak bu omurun dikensi çıkıntısı düzeyindedir.','Kürek kemiği alt açısı = T7'],
['thoracic vertebra 8','Vertebra thoracica VIII','8. sırt omuru (T8)','V. cava inferior diyaframı bu omur düzeyinde geçer.','Diyafram delikleri: T8 v. cava, T10 yemek borusu, T12 aorta'],
['thoracic vertebra 9','Vertebra thoracica IX','9. sırt omuru (T9)','Tipik sırt omurudur; kaburgalarla eklem yapar. Göğüs kemiğinin alt ucu (processus xiphoideus) yaklaşık bu düzeydedir.',''],
['thoracic vertebra 10','Vertebra thoracica X','10. sırt omuru (T10)','Yemek borusu diyaframı bu omur düzeyinde, n. vagus dallarıyla birlikte geçer. Gövdesinde 10. kaburga için tek tam eklem yüzü bulunur.',''],
['thoracic vertebra 11','Vertebra thoracica XI','11. sırt omuru (T11)','Gövdesinde 11. kaburga için tek tam eklem yüzü vardır; enine çıkıntısında kaburga eklem yüzü bulunmaz, çünkü 11. kaburga yüzen kaburgadır.',''],
['thoracic vertebra 12','Vertebra thoracica XII','12. sırt omuru (T12)','Sırt omurlarının sonuncusudur; biçimi bel omurlarına geçiş gösterir. Aorta diyaframı bu düzeyde geçer ve truncus coeliacus bu düzeyde çıkar. Sırt-bel geçişi kırıkların sık görüldüğü yerdir.',''],
['vertebral bone 1','Atlas [C I]','Atlas (1. boyun omuru)','Gövdesi ve dikensi çıkıntısı olmayan halka biçimli omurdur; kafatasını taşır. Oksipital kemikle yaptığı eklem başın öne-arkaya (evet) hareketini sağlar. Modeldeki adı: vertebral bone 1.','Atlas dünyayı (kafayı) taşır; evet hareketi'],
['vertebral bone 2','Axis [C II]','Aksis (2. boyun omuru)','Gövdesinden yukarı uzanan diş çıkıntısı (dens) atlasın içinde mil görevi yapar; başın sağa-sola (hayır) dönüşü bu eklemde olur. Dens kırığı ya da arkasındaki bağın yırtılması omuriliği ezebilir. Modeldeki adı: vertebral bone 2.','Aksis = eksen; hayır hareketi'],
['mammalian cervical vertebra 3','Vertebra cervicalis III','3. boyun omuru (C3)','Tipik boyun omurudur: gövdesi küçük, dikensi çıkıntısı kısa ve çatallıdır; enine çıkıntısındaki delikten (foramen transversarium) a. vertebralis geçer. Dil kemiği (os hyoideum) bu düzeydedir.',''],
['mammalian cervical vertebra 4','Vertebra cervicalis IV','4. boyun omuru (C4)','Tipik boyun omurudur. A. carotis communis bu düzeyde (tiroit kıkırdağın üst kenarı) ikiye ayrılır.',''],
['mammalian cervical vertebra 5','Vertebra cervicalis V','5. boyun omuru (C5)','Tipik boyun omurudur; tiroit kıkırdak bu düzeydedir. C5-C6 aralığı boyun fıtığının en sık görüldüğü yerlerdendir.',''],
['mammalian cervical vertebra 6','Vertebra cervicalis VI','6. boyun omuru (C6)','Enine çıkıntısının ön tümseği büyüktür (tuberculum caroticum); a. carotis communis buraya bastırılabilir. A. vertebralis enine çıkıntı deliklerine bu omurdan girer; krikoit kıkırdak, gırtlağın soluk borusuna ve yutağın yemek borusuna geçişi bu düzeydedir.','C6 = krikoit kıkırdak düzeyi'],
['mammalian cervical vertebra 7','Vertebra cervicalis VII (vertebra prominens)','7. boyun omuru (C7, vertebra prominens)','Dikensi çıkıntısı uzundur ve çatallı değildir; ensede en belirgin ele gelen çıkıntıdır, omurları saymada başlangıç noktası olarak kullanılır. Enine çıkıntı deliğinden a. vertebralis geçmez, yalnız küçük venler geçer.','Ensede ele gelen çıkıntı = C7'],
];
export const KADIN = {};
for (const [en, la, tr, fn, ip] of K) KADIN[en] = { anahtar: 'kd:' + en, la, tr, fn, ip };
